INSERT INTO "recall_pair" VALUES(1,1,'Juvenile western Alaskan Chinook enter Kuskokwim Bay in June at what average FL?','87 mm',8,0);
INSERT INTO "recall_pair" VALUES(2,1,'Juvenile western Alaskan Chinook reach what average FL by end of August, first summer at sea?','190–220 mm',8,0);
INSERT INTO "recall_pair" VALUES(3,1,'Juvenile Chinook hold what depth on the eastern Bering Sea shelf their first summer?','Shallow water, <50 m',8,0);
INSERT INTO "recall_pair" VALUES(4,2,'Yukon River Chinook become piscivorous at what length in what water?','85–90 mm, in freshwater',4,0);
INSERT INTO "recall_pair" VALUES(5,2,'Fish make up what share of juvenile Chinook diet in the Yukon delta during seaward migration?','~90%',5,0);
INSERT INTO "recall_pair" VALUES(6,2,'Yukon River Chinook eat what through their first summer of marine residency?','Predominantly fish — piscivory holds from June on',4,0);
INSERT INTO "recall_pair" VALUES(7,3,'Juvenile Chinook growth in the northern Bering Sea peaks when?','Mid-July',12,0);
INSERT INTO "recall_pair" VALUES(8,4,'Bioenergetic models flag what as a significant effect on juvenile Chinook growth rates?','Temperature',12,0);
INSERT INTO "recall_pair" VALUES(9,5,'SE Alaska rivers produce predominantly what smolt type of Chinook?','Yearling smolts',10,0);
INSERT INTO "recall_pair" VALUES(10,5,'SEAK Chinook smolt outmigration peaks when?','Early May',10,0);
INSERT INTO "recall_pair" VALUES(11,5,'SEAK Chinook smolts leave at what size?','54–120 mm, averaging ~74 mm and 4 g',10,0);
INSERT INTO "recall_pair" VALUES(12,5,'Ocean-age-0 SEAK Chinook average what size by late June, inshore vs strait?','136 mm / 28 g inshore; 171 mm / 56 g strait',10,0);
INSERT INTO "recall_pair" VALUES(13,5,'Ocean-age-0 SEAK Chinook average what size by September, inshore vs Icy Strait?','210 mm / 114 g inshore; 269 mm / 282 g Icy Strait',10,0);
INSERT INTO "recall_pair" VALUES(14,6,'British Columbia Chinook become primarily piscivorous at what size?','50–100 g, or 160–200 mm',3,0);
INSERT INTO "recall_pair" VALUES(15,7,'Puget Sound Chinook begin piscivory at what length, inshore vs offshore?','70 mm inshore, 130 mm offshore',1,0);
INSERT INTO "recall_pair" VALUES(16,8,'California Current juvenile Chinook diet changes how as they move offshore?','Invertebrates first, then piscivory — juvenile rockfish and anchovy',9,0);
INSERT INTO "recall_pair" VALUES(17,9,'Juvenile Chinook feed primarily on what four fish species in the northern Bering Sea?','Capelin, Arctic sand lance, Pacific herring, rainbow smelt',10,0);
INSERT INTO "recall_pair" VALUES(18,9,'Juvenile Chinook''s fish prey sit in what northern Bering Sea habitat?','Shallow/nearshore',10,0);
INSERT INTO "recall_pair" VALUES(19,10,'Northern vs southern eastern Bering Sea juvenile Chinook take what primary prey?','Capelin north; sand lance and walleye pollock south — sand lance consistent in both',12,0);
INSERT INTO "recall_pair" VALUES(20,10,'Juvenile Chinook in the Bering Sea take fish of what age class?','Age-0',12,0);
INSERT INTO "recall_pair" VALUES(21,11,'Invertebrates matter most to juvenile Chinook in what northern Bering Sea location?','Shallow habitats of Norton Sound',12,0);
INSERT INTO "recall_pair" VALUES(22,11,'Juvenile Chinook invertebrate prey in the northern Bering Sea is mostly what?','Large inverts — crab megalops (Chionoecetes) and shrimp (Pandalus); variable, can include freshwater insects',12,0);
INSERT INTO "recall_pair" VALUES(23,12,'Euphausiids show up more in juvenile SEAK Chinook caught where?','Inlets',11,0);
INSERT INTO "recall_pair" VALUES(24,12,'Euphausiids in the juvenile SEAK Chinook diet trend how June through September?','Rising share every month',11,0);
INSERT INTO "recall_pair" VALUES(25,13,'BC juvenile Chinook eat what on ocean entry and through summer?','Zooplankton and insects — mainly decapods, euphausiids, hyperiid amphipods',10,0);
INSERT INTO "recall_pair" VALUES(26,14,'Chinook in estuaries with the smallest wetland losses fed extensively on what?','Freshwater insects — mayflies, stoneflies, caddisflies',8,0);
INSERT INTO "recall_pair" VALUES(27,15,'Regional diet differences in juvenile Chinook along the CCS come from what?','Variability in the forage base and environmental conditions',10,0);
INSERT INTO "recall_pair" VALUES(28,16,'Russian Chinook diets differ how across juvenile, immature, and mature?','They don''t — all eat fish, squid (mainly Gonatidae), and euphausiids',12,0);
INSERT INTO "recall_pair" VALUES(29,17,'Russian Chinook of all life stages eat what three things?','Fish, squid (mainly Gonatidae), euphausiids',12,0);
INSERT INTO "recall_pair" VALUES(30,18,'Larger Asian Chinook come up in bottom/near-bottom trawls eating mostly what?','Adult squid Berryteuthis magister',8,0);
INSERT INTO "recall_pair" VALUES(31,19,'Immature Chinook on the eastern Bering Sea shelf and basin forage predominantly on what?','Fish and squid',12,0);
INSERT INTO "recall_pair" VALUES(32,19,'Beyond fish and squid, what prey matters to Chinook in the Bering Sea basin?','Euphausiids',12,0);
INSERT INTO "recall_pair" VALUES(33,20,'The largest component of the Chinook winter diet is what?','Squid',6,0);
INSERT INTO "recall_pair" VALUES(34,20,'Berryteuthis magister and Gonatopsis borealis together make up what share of winter stomach content weight?','74–82%',5,0);
INSERT INTO "recall_pair" VALUES(35,21,'Chinook in SEAK coastal habitats take what three primary prey species?','Capelin, sand lance, Pacific herring',5,0);
INSERT INTO "recall_pair" VALUES(36,21,'Fish make up what share of immature Chinook stomach contents by weight in SEAK marine waters?','65%',5,0);
INSERT INTO "recall_pair" VALUES(37,21,'Capelin aside, what fish are secondary prey for immature SEAK Chinook?','Pacific sand lance, Pacific herring, lanternfishes, walleye pollock',5,0);
INSERT INTO "recall_pair" VALUES(38,22,'Troll-caught ocean-age-2+ Chinook in SEAK took what top prey, at what share?','Pacific herring, 60–68% of stomach contents by volume',11,0);
INSERT INTO "recall_pair" VALUES(39,22,'Second most frequent prey of ocean-age-2+ SEAK Chinook?','Sand lance',11,0);
INSERT INTO "recall_pair" VALUES(40,22,'Ocean-age-2+ Chinook get access to herring because of what?','Their larger size',11,0);
INSERT INTO "recall_pair" VALUES(41,23,'Herring vs sand lance dominate age-2+ SEAK Chinook in which waters?','Herring inside, sand lance outside',11,0);
INSERT INTO "recall_pair" VALUES(42,23,'Squid turns up more in SEAK Chinook caught in which waters?','Inside waters',11,0);
INSERT INTO "recall_pair" VALUES(43,24,'Squid makes up a bigger share of adult salmon diet in what part of the northern California Current?','The more open waters',8,0);
INSERT INTO "recall_pair" VALUES(44,24,'Returning northern California Current adults eat largely what before spawning?','California sardine, Pacific herring, northern anchovy, euphausiids',8,0);
INSERT INTO "recall_pair" VALUES(45,33,'Resident Chinook predation June–August could impose what mortality on the Puget Sound juvenile Chinook cohort?','49–59% — cannibalism',10,0);
INSERT INTO "recall_pair" VALUES(46,25,'Tagging studies put salmon shark mortality of Bering Sea Chinook at what rate?','40%',3,0);
INSERT INTO "recall_pair" VALUES(47,26,'SEAK Chinook have what three major large predators?','Resident killer whales, sea lions, salmon sharks',11,0);
INSERT INTO "recall_pair" VALUES(48,27,'Resident Chinook eating juveniles June–August could cost the Puget Sound cohort what mortality?','49–59%',10,0);
INSERT INTO "recall_pair" VALUES(49,28,'Salish Sea Chinook have what two primary marine mammal predators?','Harbor seals and killer whales',10,0);
INSERT INTO "recall_pair" VALUES(50,28,'The Strait of Georgia holds the world''s highest density of what?','Harbor seals',10,0);
INSERT INTO "recall_pair" VALUES(51,29,'Harbor seals on the Puntledge River learned what specialized foraging behavior?','Congregating at night beneath two bridges to take migrating smolts — previously undocumented nocturnal foraging',10,0);
INSERT INTO "recall_pair" VALUES(52,29,'The Puntledge River bridge seals took what share of the chum run, at what nightly rate?','14.5%, averaging 140,000 chum fry per night',10,0);
INSERT INTO "recall_pair" VALUES(53,29,'The Puntledge River bridge seals took what share of the coho run, at what nightly rate?','15%, about 13,000 smolts per night',10,0);
INSERT INTO "recall_pair" VALUES(54,30,'Pinniped predation on Salish Sea Chinook compares how to killer whale predation?','Estimated to be equal',10,0);
INSERT INTO "recall_pair" VALUES(55,31,'Chinook make up what share of salmon consumed by Salish Sea killer whales in summer?','85%',10,0);
INSERT INTO "recall_pair" VALUES(56,31,'Besides Chinook, Salish Sea killer whales regularly eat what salmon, and why?','Chum — also large and high-lipid',10,0);
INSERT INTO "recall_pair" VALUES(57,32,'California Current System predators with the greatest impact on Chinook are what?','Piscivorous birds in the estuary and at sea, predatory fish, and to a degree marine mammals',10,0);
INSERT INTO "recall_pair" VALUES(58,34,'Chinook salmon productivity has trended how, starting about when?','General decline, starting around 2000',12,0);
INSERT INTO "recall_pair" VALUES(59,35,'Juvenile mortality in Yukon River Chinook is size-selective, yet average juvenile size correlates with what?','Neither survival nor adult returns',11,0);
INSERT INTO "recall_pair" VALUES(60,36,'Wild vs hatchery SEAK stocks show what marine survival, despite what size difference?','Wild similar or higher, even though wild smolts enter substantially smaller',11,0);
INSERT INTO "recall_pair" VALUES(61,37,'West coast Vancouver Island Chinook survival is consistently low under what condition?','El Niño events',11,0);
INSERT INTO "recall_pair" VALUES(62,38,'Juvenile Chinook transiting industrially contaminated Puget Sound estuaries survive at what rate?','45% lower than those not emigrating through contaminated sites',11,0);
INSERT INTO "recall_pair" VALUES(63,39,'Early marine survival of Salish Sea Chinook is determined largely by what, and for which fish especially?','Conditions near their source river/estuary — especially sub-yearlings',10,0);
INSERT INTO "recall_pair" VALUES(64,40,'Salish Sea trawl surveys say what about predation as a regulator of early marine salmon abundance?','It isn''t the primary mechanism',10,0);
INSERT INTO "recall_pair" VALUES(65,41,'Upwelling timing in California helps or harms juvenile survival depending on what?','Whether enough time has passed to set up productivity — roughly 3 months',10,0);
INSERT INTO "recall_pair" VALUES(66,42,'Chinook survivals along the California Current System covary at what spatial scale, matching what?','~700 km — nearly the spatial coherence of upwelling',10,0);
INSERT INTO "recall_pair" VALUES(67,43,'Chinook ocean life along the eastern Pacific Rim breaks into what three phases?','Juvenile seaward migration after smolting; immature rearing in coastal and oceanic waters; adult return migration to natal streams',6,0);
INSERT INTO "recall_pair" VALUES(68,43,'The juvenile seaward migration phase of Chinook ocean life spans what period?','The first months of ocean life, until winter',6,0);
INSERT INTO "recall_pair" VALUES(69,43,'The immature rearing phase of Chinook ocean life lasts how long?','Up to 5 years of ocean life',6,0);
INSERT INTO "recall_pair" VALUES(70,43,'The adult return migration phase of Chinook ocean life spans what period?','The last 4–10 months of ocean life',6,0);
INSERT INTO "recall_pair" VALUES(71,44,'Chinook ocean migration distances range from what to what?','As little as 100 km up to 2,500 km north and/or west',12,0);
INSERT INTO "recall_pair" VALUES(72,44,'Chinook are often prevalent in what coastal waters?','Around the rim of the Gulf of Alaska, from SE Alaska to the Aleutian chain',12,0);
INSERT INTO "recall_pair" VALUES(73,44,'The return migration of maturing Chinook is notable for what?','It''s the most rapid phase — sometimes only weeks',12,0);
INSERT INTO "recall_pair" VALUES(74,45,'Extreme ocean migrations in Chinook tend to be mirrored by what?','Extensive up-river spawning migrations — to interior or headwater locations in large river systems',12,0);
INSERT INTO "recall_pair" VALUES(75,46,'Asian Chinook mature mostly at what ages?','1.2, 1.3, or 1.4',12,0);
INSERT INTO "recall_pair" VALUES(76,47,'Yukon River Chinook undertake a migration of what length, notable why?','Up to 3,200 km — potentially the longest salmon migration in the world',9,0);
INSERT INTO "recall_pair" VALUES(77,47,'Yukon River Chinook pass what dam on their migration?','The Whitehorse Rapids dam',9,0);
INSERT INTO "recall_pair" VALUES(78,48,'Western Alaska Chinook start their up-river spawning migration when?','Shortly after river ice break-up, typically late May, peaking in June',12,0);
INSERT INTO "recall_pair" VALUES(79,48,'Run timing in the Nushagak and Kuskokwim compares how to the Yukon?','Slightly earlier',12,0);
INSERT INTO "recall_pair" VALUES(80,48,'Yukon River Chinook entry is stock structured how?','Upper-drainage stocks arrive earlier than lower-drainage stocks',12,0);
INSERT INTO "recall_pair" VALUES(81,49,'Chinook migration rates in the Kuskokwim and Nushagak compare how to the Yukon?','Generally slower',5,0);
INSERT INTO "recall_pair" VALUES(82,49,'Typical Chinook migration rate in the Kuskokwim River?','19–25 km/day',4,0);
INSERT INTO "recall_pair" VALUES(83,49,'Typical Chinook migration rate in the Nushagak River?','11–15 km/day',4,0);
INSERT INTO "recall_pair" VALUES(84,50,'Western Alaska Chinook typically mature at what ages?','1.2, 1.3, 1.4',12,0);
INSERT INTO "recall_pair" VALUES(85,50,'Female vs male Chinook maturation timing in Alaska stocks runs how?','Females mature later than males',12,0);
INSERT INTO "recall_pair" VALUES(86,51,'Upper Yukon Chinook mature when relative to Nushagak and Kuskokwim fish, and why?','Later — the higher energetic demand of reaching the upper Yukon drainage',12,0);
INSERT INTO "recall_pair" VALUES(87,52,'Chinook associate with what temperatures and depths compared to other Pacific salmon?','Colder (to 1°C) and deeper',12,0);
INSERT INTO "recall_pair" VALUES(88,53,'Sub-yearling Chinook juveniles stay within what range of their natal river their first summer and fall?','100–300 km',12,0);
INSERT INTO "recall_pair" VALUES(89,53,'Sub-yearling Chinook juveniles move which way during winter and the following spring?','Northward',12,0);
INSERT INTO "recall_pair" VALUES(90,54,'Asian Chinook migrate out to the Pacific Ocean at what temperature?','When temperatures drop to 7°C',12,0);
INSERT INTO "recall_pair" VALUES(91,55,'Juvenile Chinook exit the northern Bering Sea shelf how, and before what?','Migrating against the northward coastal currents, before winter sea ice forms',12,0);
INSERT INTO "recall_pair" VALUES(92,55,'Juvenile Chinook sit at what depth relative to pink and chum in the northern Bering Sea?','Shallower',12,0);
INSERT INTO "recall_pair" VALUES(93,56,'Western Alaskan salmon other than Chinook rear where instead?','The Gulf of Alaska, rather than the Bering Sea',12,0);
INSERT INTO "recall_pair" VALUES(94,57,'Western Alaska Chinook may use what Bering Sea migratory corridor, at what age especially?','The northwest-flowing currents along the eastern Bering Sea shelf break — particularly age 1.1',12,0);
INSERT INTO "recall_pair" VALUES(95,58,'Few juvenile Salish Sea Chinook appear on the BC continental shelf until when, implying what?','Until their first winter at sea — they reside in the Strait of Georgia and Puget Sound for an extended period',11,0);
INSERT INTO "recall_pair" VALUES(96,59,'Juvenile Chinook off Oregon and Washington behave how, to what end?','They reduce southerly transport and offshore advection, staying on the productive shelf to feed',10,0);
INSERT INTO "recall_pair" VALUES(97,60,'What is suggested as a major catalyst for salmonid speciation?','Climatic cooling and the subsequent evolution of anadromy',12,0);
INSERT INTO "recall_pair" VALUES(98,61,'Oncorhynchus diverged from Salvelinus when?','Late Oligocene, ~25 Ma',12,0);
INSERT INTO "recall_pair" VALUES(99,61,'Chinook and coho diverged from each other when?','9 Ma',12,0);
INSERT INTO "recall_pair" VALUES(100,62,'The major genetic lineages of Chinook descend from a common ancestor how long ago?','50–100 ka',12,0);
INSERT INTO "recall_pair" VALUES(101,63,'The stream-type vs ocean-type Chinook distinction holds up where?','Really only the upper Columbia — elsewhere the evidence is scant',12,0);
INSERT INTO "recall_pair" VALUES(102,64,'DNA sequence evidence of parallelism in Chinook shows what about life-history types?','Similar life-history types evolved by different evolutionary pathways',12,0);
INSERT INTO "recall_pair" VALUES(103,65,'Chinook life history traits are structured how across geography?','Nearby fish resemble each other, but there are few unique populations — a steady, windy continuum',12,0);
INSERT INTO "recall_pair" VALUES(104,66,'Chinook of what origin dominate the west Pacific?','Russian stocks',12,0);
INSERT INTO "recall_pair" VALUES(105,66,'Chinook of what origin dominate the west and central Bering Sea?','Alaska-origin stocks',12,0);
INSERT INTO "recall_pair" VALUES(106,67,'Scale pattern analysis separates eastern from western Kamchatka Chinook at what accuracy?','94–95%',12,0);
INSERT INTO "recall_pair" VALUES(107,68,'Western Alaskan Chinook make up what share of Bering Sea driftnet catches?','~80%',12,0);
INSERT INTO "recall_pair" VALUES(108,68,'Western Alaskan Chinook make up what share of North Pacific driftnet catches?','~30%',12,0);
INSERT INTO "recall_pair" VALUES(109,69,'Western Alaskan Chinook contribute to the southern shelf most and least in what seasons?','Highest in winter, least in summer',12,0);
INSERT INTO "recall_pair" VALUES(110,69,'North Pacific stocks peak on the shelf when, and are confined where?','Highest in summer, largely limited to the southern shelf',12,0);
INSERT INTO "recall_pair" VALUES(111,70,'Yukon River Chinook distribute where relative to other western Alaskan stocks?','Farther north',12,0);
INSERT INTO "recall_pair" VALUES(112,71,'Chinook in SEAK and Gulf of Alaska coastal waters originate from where?','Hundreds of streams and rivers from Alaska south to California',11,0);
INSERT INTO "recall_pair" VALUES(113,72,'Juvenile Chinook catches on the continental shelf in spring and summer are dominated by what stock, and why?','Upper Columbia River yearling (spring-run) Chinook — local stocks are still nearshore',11,0);
INSERT INTO "recall_pair" VALUES(114,72,'Juvenile Chinook shelf catches shift to what stock by fall, holding through when?','Local stocks — dominant through the winter',11,0);
INSERT INTO "recall_pair" VALUES(115,73,'How many Chinook salmon Evolutionarily Significant Units are ESA-listed, out of how many?','9 of 17, endangered or threatened',12,0);
INSERT INTO "recall_pair" VALUES(116,74,'Chinook salmon populations in the northeast Pacific span what range?','Central California (Sacramento River) north through Kotzebue Sound, Alaska',10,0);
INSERT INTO "recall_pair" VALUES(117,74,'Chinook salmon have been infrequently reported in what waters beyond their usual range?','Along Arctic shores into Canada, including the McKenzie River',10,0);
INSERT INTO "recall_pair" VALUES(118,74,'The scientific name of Chinook salmon?','Oncorhynchus tshawytscha',10,0);
INSERT INTO "recall_pair" VALUES(119,75,'Artificial propagation of Chinook salmon began where and how long ago?','The Baird Hatchery on the McCloud River, California — 140 years ago',12,0);
INSERT INTO "recall_pair" VALUES(120,76,'Aggregate Chinook salmon releases in the North Pacific have averaged how many per year over the past decade?','254 million',12,0);
INSERT INTO "recall_pair" VALUES(121,77,'Alaska releases how many hatchery Chinook salmon?','8–12 million',12,0);
INSERT INTO "recall_pair" VALUES(122,77,'Canada releases how many hatchery Chinook salmon?','Tens of millions',12,0);
INSERT INTO "recall_pair" VALUES(123,77,'The continental US releases how many hatchery Chinook salmon?','~200 million',12,0);
INSERT INTO "recall_pair" VALUES(124,78,'A coded-wire tag is what, and goes where in a fish?','A 0.25 × 1.1 mm micro-wire etched with an identifying code, injected into the snout',12,0);
INSERT INTO "recall_pair" VALUES(125,78,'A coded-wire tag is magnetized why?','To enable detection of the wire',12,0);
INSERT INTO "recall_pair" VALUES(126,79,'Juvenile Chinook in coastal Asia aggregate how, and forage with what species?','In small groups, foraging with coho salmon',12,0);
INSERT INTO "recall_pair" VALUES(127,79,'Juvenile Chinook in Asia change their aggregation how once offshore?','They form dense aggregations',12,0);
INSERT INTO "recall_pair" VALUES(128,80,'What two island groups are squid spawning areas?','The Commander Islands and the north Kurile Islands',12,0);
INSERT INTO "recall_pair" VALUES(129,81,'Sea lice infection rate and load in the southwest Bering Sea, June–July?','49% infection rate, 2.1 lice per fish',12,0);
INSERT INTO "recall_pair" VALUES(130,81,'Sea lice infection rate and load in the northwest Pacific, June–August?','92.8% infection rate, 7.0 lice per fish',12,0);
INSERT INTO "recall_pair" VALUES(131,82,'Chinook smolts enter the eastern Bering Sea primarily from what three western Alaska drainages?','The Yukon, Kuskokwim, and Nushagak rivers',12,0);
INSERT INTO "recall_pair" VALUES(132,83,'Average Chinook run size in the Yukon River, and the Canadian-origin share?','~236,000 total; 118,000 Canadian-origin',4,0);
INSERT INTO "recall_pair" VALUES(133,83,'Average Chinook run size in the Kuskokwim River?','259,000',4,0);
INSERT INTO "recall_pair" VALUES(134,83,'Average Chinook run size in the Nushagak River?','236,000',4,0);
INSERT INTO "recall_pair" VALUES(135,84,'Chinook salmon production tracks what, rather than river size?','The amount of suitable spawning and rearing habitat',12,0);
INSERT INTO "recall_pair" VALUES(136,85,'Chinook rank where among Pacific salmon for size and fecundity?','Largest size and highest fecundity of all Pacific salmon',12,0);
INSERT INTO "recall_pair" VALUES(137,85,'Chinook egg size and emergent fry size rank where among Pacific salmon?','Relatively large eggs; the largest emergent fry',12,0);
INSERT INTO "recall_pair" VALUES(138,86,'Driftnet fishing for salmon and squid closed in what year, under what?','1993, under the UN moratorium on driftnet fishing in international waters',12,0);
INSERT INTO "recall_pair" VALUES(139,87,'The eastern Bering Sea cold pool sits where and forms from what?','The northern eastern Bering Sea shelf — a by-product of winter sea ice',12,0);
INSERT INTO "recall_pair" VALUES(140,88,'Pacific herring are scarce in northern Bering Sea juvenile Chinook diets possibly why?','Herring outgrow the prey size window available to juvenile Chinook',12,0);
INSERT INTO "recall_pair" VALUES(141,89,'Clinical Ichthyophonus infection in Chinook presents how?','Parasite loads visible to the naked eye in muscle and organs, softened muscle tissue, a distinctive odor',11,0);
INSERT INTO "recall_pair" VALUES(142,90,'SEAK coho compare in size to same ocean-age SEAK Chinook by their second ocean summer how?','Three times larger',11,0);
INSERT INTO "recall_pair" VALUES(143,91,'Salmon louse prevalence in coastal British Columbia compares how to Alaska?','Lower in coastal BC',11,0);
INSERT INTO "recall_pair" VALUES(144,92,'The ''Salish Sea'' covers what area?','The western margin of the Strait of Juan de Fuca, all of Puget Sound, north to Desolation Sound in the Strait of Georgia',6,0);
INSERT INTO "recall_pair" VALUES(145,93,'Salmon use estuaries for what three things?','Physiological acclimation, initial foraging in marine conditions, refuge from predators',11,0);
INSERT INTO "recall_pair" VALUES(146,94,'Juvenile Chinook may raise feeding intensity through what behaviors?','Following evolutionarily embedded navigational cues, tracking increasing prey gradients, residing at or near oceanographic fronts',10,0);
INSERT INTO "recall_pair" VALUES(147,95,'What statistical evidence supports CCS Chinook using fronts, and where?','A significant relationship between salmon production and probability of frontal development during the first months at sea, in the Gulf of the Farallones',10,0);
INSERT INTO "recall_pair" VALUES(148,95,'Chinook concentrate around what feature in the Columbia River plume, and why?','Salinity fronts — prey was disproportionately more abundant there',10,0);
INSERT INTO "recall_pair" VALUES(149,151,'The Richardson number is the ratio of what to what?','Stabilizing forces (density difference across a boundary) to destabilizing forces (shear across it)',6,0);
INSERT INTO "recall_pair" VALUES(150,151,'A low Richardson number means what for internal waves?','They destabilize, generating internal turbulence',6,0);
INSERT INTO "recall_pair" VALUES(151,159,'In the transition zone between mixed and stratified shelf water, what decides which one wins on a given day?','The strength of the tidal force — where you are in the lunar cycle',10,0);
INSERT INTO "recall_pair" VALUES(152,160,'Fully mixed areas over shallow water can bloom nearly year-round — why?','Material picked up from the benthos gives a nutrient boost that outweighs the time spent below the euphotic zone',9,0);
INSERT INTO "recall_pair" VALUES(153,160,'Over shallow mixed banks, what still makes production vary through the year?','Changes in solar inclination',9,0);
INSERT INTO "recall_pair" VALUES(154,161,'Tidally mixed waters warm more slowly for what reason?','Stratification can''t set in',6,0);
INSERT INTO "recall_pair" VALUES(155,161,'Zooplankton build up more slowly in tidally mixed waters because of what?','The suppressed warming — temperature drives zooplankton growth',6,0);
INSERT INTO "recall_pair" VALUES(156,162,'A river plume is what?','Surface outflow coming directly from a river',7,0);
INSERT INTO "recall_pair" VALUES(157,162,'An estuarine plume is what?','Outflow leaving an estuary, so it has already mixed with salt water',7,0);
INSERT INTO "recall_pair" VALUES(158,163,'What pushes a plume around?','Currents, wind stress, tidal forces, and Coriolis',9,0);
INSERT INTO "recall_pair" VALUES(159,163,'Over what timescale does a plume change position?','Repeatedly over a single day',9,0);
INSERT INTO "recall_pair" VALUES(160,164,'The peak in river runoff often coincides with what?','A diatom bloom near the river mouth',6,0);
INSERT INTO "recall_pair" VALUES(161,165,'Estuarine plumes arrive nutrient-poorer than river plumes because of what?','Productivity in the estuary has already taken some out',6,0);
INSERT INTO "recall_pair" VALUES(162,165,'Why do estuarine plumes still deliver plenty of nutrients despite that uptake?','Human-driven loads are high enough that plenty is left',6,0);
INSERT INTO "recall_pair" VALUES(163,165,'What do estuarine currents do to nutrients in the outgoing water?','Entrain them, carrying them seaward',6,0);
INSERT INTO "recall_pair" VALUES(164,166,'Fresh water at the surface sets up stratification earlier for what reason?','It''s lighter than salt water',6,0);
INSERT INTO "recall_pair" VALUES(165,166,'Earlier stratification from fresh water leads to what?','Earlier blooms',6,0);
INSERT INTO "recall_pair" VALUES(166,148,'An estuary is defined as what?','A semi-enclosed coastal body of water with a free connection to the open sea, within which sea water is measurably diluted with fresh water',7,0);
INSERT INTO "recall_pair" VALUES(167,149,'Estuarine circulation is what pattern of flow?','Fresh water flowing out on top, over a deeper undercurrent of salt water flowing in',5,0);
INSERT INTO "recall_pair" VALUES(168,149,'Estuarine circulation is driven by what?','Buoyancy',5,0);
INSERT INTO "recall_pair" VALUES(169,150,'Why does the fresh outflowing layer of an estuary get thicker and more saline seaward?','Turbulence mixes salt water up into it as it goes',6,0);
INSERT INTO "recall_pair" VALUES(170,150,'What lets the fresh layer flow out over the salt water in the first place?','Being lighter, it piles up higher, giving it a head to flow out from',6,0);
INSERT INTO "recall_pair" VALUES(171,152,'When a river''s flow is strong enough, what does it do to the salt water?','Pushes it out away from the coast as a wedge of fresh water',10,0);
INSERT INTO "recall_pair" VALUES(172,152,'What sets how far offshore the fresh wedge reaches?','The strength of the river flow',10,0);
INSERT INTO "recall_pair" VALUES(173,152,'Where do heavy particles flocculate and sink in a wedge estuary?','At the salinity boundary — the edge of the wedge',10,0);
INSERT INTO "recall_pair" VALUES(174,152,'Wide deposition zones in some estuaries come from what?','The edge of the wedge migrating over time, so deposition follows it',10,0);
INSERT INTO "recall_pair" VALUES(175,153,'Some estuaries have no classic estuarine circulation at all — why?','Tidal forces are strong enough to totally mix the water',9,0);
INSERT INTO "recall_pair" VALUES(176,153,'What do you get instead of layered circulation in a totally tidally mixed estuary?','A salinity gradient running from the land to the sea',9,0);
INSERT INTO "recall_pair" VALUES(177,154,'A fjord''s shape is what?','A sill followed by a deep basin',8,0);
INSERT INTO "recall_pair" VALUES(178,154,'New deep, cold, saline water enters a fjord only when what happens?','There''s enough activity of the right kind to force water over the sill',8,0);
INSERT INTO "recall_pair" VALUES(179,154,'In a fjord, where does fresh water go?','Over the surface and across the sill',8,0);
INSERT INTO "recall_pair" VALUES(180,155,'What can dominate the processes at a fjord''s sill?','Wind stress, tidal forces, or freshwater runoff',9,0);
INSERT INTO "recall_pair" VALUES(181,156,'What do the salt undercurrent, fresh overcurrent and tides give animals in an estuary?','A variety of currents and countercurrents they''ve learned to ride to get where they need to be',6,0);
INSERT INTO "recall_pair" VALUES(182,105,'What does water moving across benthic plants do for them?','Breaks the diffusion limitation — e.g. phosphorus uptake rises with stronger currents',2,0);
INSERT INTO "recall_pair" VALUES(183,105,'How does kelp photosynthesis respond to increasing current?','It increases asymptotically',2,0);
INSERT INTO "recall_pair" VALUES(184,105,'What management strategy does the kelp/current relationship suggest?','Cutting kelp to increase flow through the forest',2,0);
INSERT INTO "recall_pair" VALUES(185,106,'What are the hollow floats on many seaweeds for?','Creating movement by taking advantage of turbulence in the water',5,0);
INSERT INTO "recall_pair" VALUES(186,107,'What do benthic plants have to do to survive extreme currents or turbidity?','Morphologically change — streamline — so they don''t get torn up',3,0);
INSERT INTO "recall_pair" VALUES(187,107,'Beyond streamlining, what else is valuable to a plant in extreme flow?','Shelter',3,0);
INSERT INTO "recall_pair" VALUES(188,108,'On bottoms with very low current, which feeders dominate?','Deposit-digesting animals',7,0);
INSERT INTO "recall_pair" VALUES(189,108,'As current over the bottom picks up, the community shifts toward what — until what?','More and more filter feeders, until the flow is too fast',7,0);
INSERT INTO "recall_pair" VALUES(190,109,'What happens to bivalves and other filter feeders without a decent current moving past?','They completely exhaust the resources around them',3,0);
INSERT INTO "recall_pair" VALUES(191,110,'The tidal stress larvae experience near the seafloor is comparable to what?','Hurricane-force winds, twice a day',6,0);
INSERT INTO "recall_pair" VALUES(192,111,'How thick is the boundary layer near the seafloor?','About 100 $\mu$m',5,0);
INSERT INTO "recall_pair" VALUES(193,111,'What is the "balloonist technique" larvae use to sample the seafloor?','Rising into the current and then dropping',5,0);
INSERT INTO "recall_pair" VALUES(194,112,'At what scale do the homogeneity assumptions of fluid mechanics stop holding in the ocean?','At scales larger than the depth of the water',5,0);
INSERT INTO "recall_pair" VALUES(195,112,'What do motions become at scales larger than the water depth?','Two-dimensional eddies — geostrophic turbulence',5,0);
INSERT INTO "recall_pair" VALUES(196,113,'As an organism''s velocity decreases, what happens to its boundary layer?','It thickens',0,0);
INSERT INTO "recall_pair" VALUES(197,114,'Skin drag (viscous drag) is caused by what?','Friction of the boundary layer',6,0);
INSERT INTO "recall_pair" VALUES(198,114,'Pressure drag is generated by what?','The need to move water out of the way and then back into place',6,0);
INSERT INTO "recall_pair" VALUES(199,118,'What sorting effect happens in the boundary layer near the bottom?','Differing settling velocities leave organics more concentrated above the bottom than inorganic particles',5,0);
INSERT INTO "recall_pair" VALUES(200,157,'Fronts are defined as what?','Regions with strong gradients',9,0);
INSERT INTO "recall_pair" VALUES(201,158,'Fronts are often found where what condition is met?','Turbulent mixing is strong enough to overcome the barrier stratification presents',8,0);
INSERT INTO "recall_pair" VALUES(202,158,'How can you approximately calculate whether mixing can overcome stratification?','Compare the water column''s potential energy before and after mixing',8,0);
INSERT INTO "recall_pair" VALUES(203,187,'Name the six kinds in the standard classification of fronts.','Tidal, shelf break, upwelling, estuarine, plume, and fronts associated with geomorphic features (headlands, islands, canyons)',7,0);
INSERT INTO "recall_pair" VALUES(204,188,'Tidal currents meeting the quickly changing bathymetry at the shelf edge generate what, which then makes a front?','Large internal waves',3,0);
INSERT INTO "recall_pair" VALUES(205,189,'A tidal front on a continental shelf sits at the meeting of what two water masses?','Stratified and unstratified water',5,0);
INSERT INTO "recall_pair" VALUES(206,189,'What moves a tidal front back and forth over time?','The changing strength of tidal currents through the lunar cycle',5,0);
INSERT INTO "recall_pair" VALUES(207,189,'Why does a tidal front''s wandering make it good for production?','The same water is mixed at some times and stratified at others, which is ideal for mixing nutrients up into it',5,0);
INSERT INTO "recall_pair" VALUES(208,190,'What do the boundaries of fronts create, which in turn creates mixing?','Eddies',10,0);
INSERT INTO "recall_pair" VALUES(209,190,'Eddy mixing at a front''s boundary boosts productivity most in what setting?','Where the surrounding water is otherwise stratified',10,0);
INSERT INTO "recall_pair" VALUES(210,191,'With stratified water on one side of a front and well-mixed water on the other, what route do nutrients take?','Under the pycnocline on the stratified side, across, and up into the mixed layer on the mixed side',8,0);
INSERT INTO "recall_pair" VALUES(211,192,'What visible sign shows that a front is a place of convergence?','Rubbish and organic debris collecting along it',6,0);
INSERT INTO "recall_pair" VALUES(212,192,'Convergence at a front is thought to occur because of what?','The currents are not exactly in geostrophic balance',6,0);
INSERT INTO "recall_pair" VALUES(213,193,'Apart from mixing, what does convergence at a front do for productivity?','Concentrates nutrients and production on its own',7,0);
INSERT INTO "recall_pair" VALUES(214,194,'Studies along fronts found that simply mixing water from the two sides does what?','Boosts productivity',8,0);
INSERT INTO "recall_pair" VALUES(215,194,'What does the productivity boost from mixing the two sides of a front imply about each water mass?','Each holds something necessary but insufficient on its own for rapid growth',8,0);
INSERT INTO "recall_pair" VALUES(216,195,'How might flagellates use their locomotory powers to beat stratification?','Swimming down through the nutricline for nutrients, then back up toward the sun',6,0);
INSERT INTO "recall_pair" VALUES(217,196,'Crossing the front between tidally mixed and stratified water can come with what change on the bottom?','A change in benthic community structure',3,0);
INSERT INTO "recall_pair" VALUES(218,197,'How often do shelf break fronts pump nutrients into the water column?','Twice daily',7,0);
INSERT INTO "recall_pair" VALUES(219,197,'Over what period do tidal fronts pump nutrients, compared with shelf break fronts?','A fortnight — so shelf break fronts give a far more continuous supply',7,0);
INSERT INTO "recall_pair" VALUES(220,198,'An upwelling front is the interface between what and what?','The upwelling and the rest of the sea, where upwelled water can push the surface no further and downwells',8,0);
INSERT INTO "recall_pair" VALUES(221,198,'Where is the greatest upwelling productivity often found?','At the upwelling front',8,0);
INSERT INTO "recall_pair" VALUES(222,199,'How is a plume front visible at the surface?','As a change in the colour of the water, usually from the salinity change',8,0);
INSERT INTO "recall_pair" VALUES(223,119,'The depth of quick nutrient change in the open ocean is called what?','The nutricline',4,0);
INSERT INTO "recall_pair" VALUES(224,120,'Light intensity at wavelength $\lambda$ and depth $z$ is given by what equation?','$I = I_o e^{-\alpha_{\lambda} z}$',6,0);
INSERT INTO "recall_pair" VALUES(225,120,'In $I = I_o e^{-\alpha_{\lambda} z}$, what are $I_o$ and $\alpha_{\lambda}$?','$I_o$ is intensity at the sea surface; $\alpha_{\lambda}$ is the absorption coefficient',6,0);
INSERT INTO "recall_pair" VALUES(226,121,'Which colour of light does the ocean absorb least quickly?','Blue',4,0);
INSERT INTO "recall_pair" VALUES(227,122,'The energy spent mixing the water column becomes what?','Potential energy stored in the water column',5,0);
INSERT INTO "recall_pair" VALUES(228,123,'Why can the mixed layer keep producing for a while without nutrients being mixed in from below?','Recycling within the layer',8,0);
INSERT INTO "recall_pair" VALUES(229,123,'What makes recycling in the mixed layer unstable in the long run?','Nutrients leak out — falling through the pycnocline, or eaten by fish that then swim away',8,0);
INSERT INTO "recall_pair" VALUES(230,124,'Recycled nitrogen shows up in what form?','Ammonia',5,0);
INSERT INTO "recall_pair" VALUES(231,124,'Nitrogen arriving from below shows up in what form?','Nitrate',5,0);
INSERT INTO "recall_pair" VALUES(232,124,'How can you tell how much production is recycled versus new?','The ratio of ammonia to nitrate',5,0);
INSERT INTO "recall_pair" VALUES(233,129,'In warmer months, day-night heating and cooling nets out to what?','Net warming',8,0);
INSERT INTO "recall_pair" VALUES(234,129,'Why does the surface warm faster under lower winds?','The top few metres where radiation is absorbed make up a greater share of the shallower mixed layer',8,0);
INSERT INTO "recall_pair" VALUES(235,139,'Name the layers of the open ocean from the surface down when solar heating shallows the mixed layer.','Mixed layer, diurnal thermocline (during the day), seasonal thermocline, then the ocean interior',5,0);
INSERT INTO "recall_pair" VALUES(236,139,'Over what timescale can the layering of the open ocean change?','Within a single day',5,0);
INSERT INTO "recall_pair" VALUES(237,145,'What makes zooplankton distribution differ from phytoplankton distribution?','Zooplankton can make extensive vertical migrations',3,0);
INSERT INTO "recall_pair" VALUES(238,145,'Where do zooplankton sit during low productivity periods, and where when it picks up?','Deep and cool during low productivity; up near the surface when productivity picks up',3,0);
INSERT INTO "recall_pair" VALUES(239,146,'In stable oligotrophic tropical systems, where are zooplankton found?','In the mixed layer, tending to sit near the thermocline',4,0);
INSERT INTO "recall_pair" VALUES(240,146,'The depth where zooplankton abundance drops off is sometimes called what?','The planktocline',4,0);
INSERT INTO "recall_pair" VALUES(241,147,'South of Iceland, how did the proportion of copepodites change between late March and early May?','From 1% to 65%',4,0);
INSERT INTO "recall_pair" VALUES(242,208,'What are Hadley cells?','The circulation of equatorial air rising, cooling, and falling again in the subtropics — the source of the trade winds',4,0);
INSERT INTO "recall_pair" VALUES(243,209,'The westerlies meander north and south in waves of roughly what length?','About 10,000 km',5,0);
INSERT INTO "recall_pair" VALUES(244,209,'Shifts in the position of the westerlies account for what?','Departures from average weather in the mid latitudes',5,0);
INSERT INTO "recall_pair" VALUES(245,210,'How many cold core rings does the Gulf Stream form a year?','About 10',6,0);
INSERT INTO "recall_pair" VALUES(246,210,'How many warm core rings does the Gulf Stream form a year?','Around 5, but extremely variable',6,0);
INSERT INTO "recall_pair" VALUES(247,210,'How do Gulf Stream warm core rings compare in size to its cold core rings?','Smaller',6,0);
INSERT INTO "recall_pair" VALUES(248,211,'What do some animals use western boundary jets for?','Travelling fast from warm water as juveniles to cold productive areas as adults',8,0);
INSERT INTO "recall_pair" VALUES(249,212,'Pink salmon power their huge migration with what?','The Alaskan gyre',3,0);
INSERT INTO "recall_pair" VALUES(250,212,'What may sockeye salmon do with the Alaskan gyre over their time at sea?','Make multiple circuits of it',3,0);
INSERT INTO "recall_pair" VALUES(251,213,'An eddy that stays affixed to the current that created it is called what?','A frontal eddy',8,0);
INSERT INTO "recall_pair" VALUES(252,214,'Why can Atlantic cold core rings be sites of vigorous blooms?','The cold water they upwell',6,0);
INSERT INTO "recall_pair" VALUES(253,215,'Which group ran a multidisciplinary study of oceanic rings?','The Ring Group',5,0);
INSERT INTO "recall_pair" VALUES(254,216,'What do cold rings carry with them into the Sargasso Sea?','The micro-fauna of the colder regions, plus lots of mesopelagic fishes',7,0);
INSERT INTO "recall_pair" VALUES(255,216,'How can a cold ring in the Sargasso be roughly aged?','By its declining number of animals over time',7,0);
INSERT INTO "recall_pair" VALUES(256,216,'How much more productive is a cold ring than the surrounding Sargasso Sea initially?','50% more',7,0);
INSERT INTO "recall_pair" VALUES(257,217,'What is one proposed mechanism for the productivity jump in warm core rings?','Surface cooling drives convective mixing that brings up the nutrients for a bloom',5,0);
INSERT INTO "recall_pair" VALUES(258,217,'What happens to zooplankton biomass in the cores of warm core rings over time?','It ticks up, following the blooms',5,0);
INSERT INTO "recall_pair" VALUES(259,217,'Where does Sargasso fauna caught up in warm core rings end up?','Carried into slope water',5,0);
INSERT INTO "recall_pair" VALUES(260,218,'Because warm and cold core rings trap fauna, what can they do?','Deliver unexpected fauna to cold and warm places respectively',4,0);
INSERT INTO "recall_pair" VALUES(261,218,'What can the fauna delivered by a ring dramatically affect?','Year-class survival of larval fish',4,0);
INSERT INTO "recall_pair" VALUES(262,125,'Along the equator, how does the depth of the mixed layer compare east to west?','Deeper in the west, shallower in the east',7,0);
INSERT INTO "recall_pair" VALUES(263,125,'Why is the western equatorial mixed layer nutrient-depleted?','It came from the eastern mixed layer, which already used the nutrients',7,0);
INSERT INTO "recall_pair" VALUES(264,125,'Where along the equator is primary productivity generally greater?','In the east',7,0);
INSERT INTO "recall_pair" VALUES(265,126,'A parcel of water that has just upwelled near the equator holds what?','High nutrients but little phytoplankton',7,0);
INSERT INTO "recall_pair" VALUES(266,126,'By the time an equatorial food web has established itself, where has its water gone?','West and spun away from the equator — which is what gives the equatorial plume its shape',7,0);
INSERT INTO "recall_pair" VALUES(267,127,'Equatorial phytoplankton production hits its minimum in which months, and why?','February–May, when slackening trade winds give high surface temperatures and reduced upwelling',6,0);
INSERT INTO "recall_pair" VALUES(268,127,'Equatorial productivity peaks in which months?','September–November',6,0);
INSERT INTO "recall_pair" VALUES(269,127,'When do the trade winds pick back up to drive the equatorial upwelling?','June–July',6,0);
INSERT INTO "recall_pair" VALUES(270,128,'How does total productivity of the Peru upwelling system compare with the eastern Pacific equatorial system?','An order of magnitude less',7,0);
INSERT INTO "recall_pair" VALUES(271,128,'Why does Peru lose to the equatorial upwelling system on total productivity despite being very productive?','Peru is high per unit area, but the equatorial system covers an enormous area',7,0);
INSERT INTO "recall_pair" VALUES(272,143,'What creates the episodic upwelling behind temporary surface plankton blooms in the open ocean?','Internal waves and mesoscale jet fronts',5,0);
INSERT INTO "recall_pair" VALUES(273,144,'What creates the upwelling in the belt around Antarctica?','Western winds and Coriolis drive water toward Antarctica while eastern winds send water north — the boundary is a divergence',4,0);
INSERT INTO "recall_pair" VALUES(274,144,'What does the Antarctic divergence make of the belt around Antarctica?','A hotspot for productivity',4,0);
INSERT INTO "recall_pair" VALUES(275,224,'What fills the centres of the oceanic gyres?','Eddies of varying energy — they are not empty',8,0);
INSERT INTO "recall_pair" VALUES(276,225,'How is the mesopelagic distributed across the world''s oceans?','More or less continuously',4,0);
INSERT INTO "recall_pair" VALUES(277,226,'Why does the North Pacific have continuous productivity even in winter?','Winter mixing there does not extend very deep',4,0);
INSERT INTO "recall_pair" VALUES(278,226,'What must North Atlantic phytoplankton do in winter that North Pacific phytoplankton need not?','Adopt strategies to tough out a very deep mixed layer',4,0);
INSERT INTO "recall_pair" VALUES(279,223,'What two mechanisms might shift salmon migration routes under El Niño?','More rain giving more runoff and stronger coastal currents, and energetic eddies the fish have to swim around',6,0);
INSERT INTO "recall_pair" VALUES(280,223,'Where has the research on El Niño shifting salmon migration routes been focused?','Fish migrating through Southeast Alaska and around Vancouver Island',6,0);
INSERT INTO "recall_pair" VALUES(281,219,'Annual plankton biomass off California is largely set by what?','The volume of the flow — higher volume, more biomass',7,0);
INSERT INTO "recall_pair" VALUES(282,220,'Besides moving the California Current, what else does ENSO shift?','The Aleutian Low',6,0);
INSERT INTO "recall_pair" VALUES(283,220,'How far north can ENSO move the boundary between Alaskan waters and the California Current?','Sometimes by 1500 km',6,0);
INSERT INTO "recall_pair" VALUES(284,221,'Which stocks do better in years of a weak California Current and weak upwelling?','Mackerel and hake',7,0);
INSERT INTO "recall_pair" VALUES(285,221,'Why do mackerel and hake recruit better when the California Current and upwelling are weak?','Fewer larvae and juveniles get advected offshore',7,0);
INSERT INTO "recall_pair" VALUES(286,221,'Why do herring off southeast Alaska have better years under El Niño?','It forces water levels up and toward the shore, giving better retention',7,0);
INSERT INTO "recall_pair" VALUES(287,222,'What does El Niño bring to Japan?','Cold water',7,0);
INSERT INTO "recall_pair" VALUES(288,222,'What do species that normally stay north of Japan, walruses among them, do in El Niño years?','Come south to Japan',7,0);
INSERT INTO "recall_pair" VALUES(289,167,'Why does upwelling on western margins bring up far fewer nutrients?','The mixed layer there is thicker',7,0);
INSERT INTO "recall_pair" VALUES(290,168,'Name the five major coastal currents associated with upwelling regions.','California, Peru, Canary, Benguela, and Somali',5,0);
INSERT INTO "recall_pair" VALUES(291,169,'Which way does the pressure gradient generated by upwelling push at depth?','Offshore — the opposite of the inshore push near the surface',8,0);
INSERT INTO "recall_pair" VALUES(292,169,'Coriolis turns the deep offshore pressure gradient under an upwelling into what?','A poleward current',8,0);
INSERT INTO "recall_pair" VALUES(293,170,'How do mountains close to the coast create a preferred location for upwelling?','They direct winds toward the coast and intensify them',7,0);
INSERT INTO "recall_pair" VALUES(294,171,'How deep is the mixed layer off Peru during an El Niño?','About 100 m',6,0);
INSERT INTO "recall_pair" VALUES(295,171,'Why does Peruvian productivity collapse in an El Niño?','The upwelling no longer reaches below the pycnocline',6,0);
INSERT INTO "recall_pair" VALUES(296,172,'What tells you upwelling is in progress next to a western coast?','The isopycnals slope upwards',5,0);
INSERT INTO "recall_pair" VALUES(297,176,'What creates the "nutrient trap" in the Canary current upwelling system?','A shoreward undercurrent that transports and upwells recycled nutrients back into the system',8,0);
INSERT INTO "recall_pair" VALUES(298,177,'Over what depth range does the Peruvian upwelling really extend?','Roughly 30–80 m',5,0);
INSERT INTO "recall_pair" VALUES(299,177,'What follows from Peruvian upwelling not reaching the bottom?','Water near the bottom is quite still, and organic matter accumulates',5,0);
INSERT INTO "recall_pair" VALUES(300,180,'What formula did Bakun use for wind stress?','$\tau = \rho_a C_d v^2$, with $\rho_a$ the density of air and $C_d$ the drag coefficient',5,0);
INSERT INTO "recall_pair" VALUES(301,180,'What value did Bakun take for the drag coefficient $C_d$?','A constant 0.0026',5,0);
INSERT INTO "recall_pair" VALUES(302,180,'How did Bakun get Ekman transport $M$ from wind stress $\tau$?','$M = \tau / f$, with $f$ the Coriolis parameter',5,0);
INSERT INTO "recall_pair" VALUES(303,181,'What happens off Oregon and Washington in the winter?','Strong downwelling',5,0);
INSERT INTO "recall_pair" VALUES(304,182,'Why does upwelling in an upwelling system change from day to day?','It depends on wind speed and direction',8,0);
INSERT INTO "recall_pair" VALUES(305,186,'Which place is the example of a western margin area with summer upwelling?','Nova Scotia',6,0);
INSERT INTO "recall_pair" VALUES(306,173,'Why are zooplankton decoupled from primary production?','Copepods and the like take weeks to complete a life cycle, not days',7,0);
INSERT INTO "recall_pair" VALUES(307,174,'Why are zooplankton in the Canary current system not food limited?','Phytoplankton respond so much faster that they exceed the zooplankton''s grazing capacity',8,0);
INSERT INTO "recall_pair" VALUES(308,174,'In the Canary current system, who is food limited?','Nobody — zooplankton also provide more food than the fish can eat',8,0);
INSERT INTO "recall_pair" VALUES(309,175,'Which fish group heavily dominates the major upwelling systems worldwide?','Clupeids',7,0);
INSERT INTO "recall_pair" VALUES(310,178,'Name the four zones you cross moving offshore along the Peruvian upwelling system.','Initial upwelling, development of phytoplankton, rapid nutrient depletion, final nutrient depletion',5,0);
INSERT INTO "recall_pair" VALUES(311,178,'Why does the Peruvian upwelling system show zones offshore rather than a uniform state?','The water moves away from shore while the food web sets itself up',5,0);
INSERT INTO "recall_pair" VALUES(312,179,'What do anchoveta do during El Niño years?','Seek out cooler water to hide in',6,0);
INSERT INTO "recall_pair" VALUES(313,179,'What is the cost to anchoveta of hiding in cooler water during El Niño?','That water is often very poor in nutrients for them',6,0);
INSERT INTO "recall_pair" VALUES(314,183,'Which species are most abundant in the California current upwelling system?','Sardines and anchovy',6,0);
INSERT INTO "recall_pair" VALUES(315,184,'Where do sardine and anchovy in the California current prefer to spawn?','The California Bight — much less upwelling, more stratification',10,0);
INSERT INTO "recall_pair" VALUES(316,184,'Why do sardine and anchovy larvae need stratified water?','In their early days they must feed within the chlorophyll maximum, which requires stratification',10,0);
INSERT INTO "recall_pair" VALUES(317,184,'What is upwelling''s paradox for sardine and anchovy?','Great for productivity, terrible for larvae — so they need a safe place to rear before exploiting it',10,0);
INSERT INTO "recall_pair" VALUES(318,185,'Where do the southern African anchovy spawning grounds sit relative to the upwelling, unlike California''s?','At the beginning of the upwelling currents rather than the terminus',4,0);
INSERT INTO "recall_pair" VALUES(319,185,'What do southern African anchovy ride from their spawning grounds to the upwelling?','The ''Good Hope Jet''',4,0);
INSERT INTO "recall_pair" VALUES(320,96,'The diffusion limitation of metabolism is what?','That unless action is taken, metabolism becomes wholly limited by the rate of molecular diffusion',4,0);
INSERT INTO "recall_pair" VALUES(321,97,'How long does molecular diffusion take to produce an effect over 100 $\mu$m?','On the order of 10 seconds',6,0);
INSERT INTO "recall_pair" VALUES(322,98,'What are plankton''s two strategies against the diffusion limitation?','Sinking and swimming',6,0);
INSERT INTO "recall_pair" VALUES(323,99,'How does the density of most phytoplankton compare with water?','Denser — diatoms are more than twice as dense',4,0);
INSERT INTO "recall_pair" VALUES(324,100,'Why do organisms in the 1–10 $\mu$m range gain nothing from sinking or swimming?','Diffusion already moves material into the cell faster than movement would — the only gain is reaching richer water',9,0);
INSERT INTO "recall_pair" VALUES(325,101,'At what diameter does swimming start to pay off substantially, and by how much?','Around 50 $\mu$m, where it can double or triple nutrient uptake',7,0);
INSERT INTO "recall_pair" VALUES(326,101,'How much benefit does movement give an organism at 10 $\mu$m?','Near negligible',7,0);
INSERT INTO "recall_pair" VALUES(327,102,'What makes eddy diffusion special compared with molecular diffusion?','It is the same for all properties — salt and heat alike',7,0);
INSERT INTO "recall_pair" VALUES(328,103,'The Reynolds number is the ratio of what to what?','Inertial forces to viscous forces',9,0);
INSERT INTO "recall_pair" VALUES(329,103,'What is the formula for the Reynolds number?','$Re = ud/v$ — velocity $u$, typical dimension $d$, kinematic viscosity $v$',9,0);
INSERT INTO "recall_pair" VALUES(330,104,'What is the formula for the Kolmogoroff length scale?','$2\pi (v^3/\epsilon)^{1/4}$ — kinematic viscosity $v$, turbulent energy dissipation $\epsilon$',3,0);
INSERT INTO "recall_pair" VALUES(331,104,'What does the Kolmogoroff length scale represent?','The distance across the smallest eddies, below which viscosity smooths everything out',3,0);
INSERT INTO "recall_pair" VALUES(332,104,'How big does the Kolmogoroff length scale typically come out?','Tens of millimetres',3,0);
INSERT INTO "recall_pair" VALUES(333,115,'What specialized feeding technique do small creatures at low Reynolds number use?','The "fling and clap"',5,0);
INSERT INTO "recall_pair" VALUES(334,116,'What experiment showed that chemoreception matters to copepods?','They captured glass particles too large to digest, so long as the chemical cues were there',5,0);
INSERT INTO "recall_pair" VALUES(335,116,'How far away can copepods sense a moving body by mechanoreception?','3–4 body lengths',5,0);
INSERT INTO "recall_pair" VALUES(336,117,'What can copepods capture that their sieves ought not to catch, and why?','Items smaller than the filaments of the sieve — the fluid dynamics at small Reynolds numbers allow it',6,0);
INSERT INTO "recall_pair" VALUES(337,130,'What are the three steps of the Gran effect?','Turbulent mixing brings nutrients up, stratification sets in and holds phytoplankton near the sun, then a bloom',7,0);
INSERT INTO "recall_pair" VALUES(338,131,'The compensation depth is what?','The depth at which photosynthetic production is balanced by respiration',6,0);
INSERT INTO "recall_pair" VALUES(339,132,'The critical depth is what?','The depth of water column over which total respiration and photosynthesis balance, assuming plankton are mixed through the whole layer',6,0);
INSERT INTO "recall_pair" VALUES(340,133,'What is the equation for the critical depth $D_{cr}$?','$I_c D_{cr} = I_0 (1 - e^{\alpha D_{cr}})/\alpha$ — $I_c$ illumination at the compensation depth, $I_0$ at the surface, $\alpha$ the absorption coefficient',0,0);
INSERT INTO "recall_pair" VALUES(341,133,'How is the critical depth equation derived?','By equating the integral of respiration to the integral of photosynthesis over a round trip through the mixed layer',0,0);
INSERT INTO "recall_pair" VALUES(342,134,'What ends the spring bloom?','It depletes the dissolved nitrogen in the water column',6,0);
INSERT INTO "recall_pair" VALUES(343,135,'As a bloom progresses, the species mix shifts toward what?','Species with flagella',6,0);
INSERT INTO "recall_pair" VALUES(344,135,'Why do flagellates take over late in a bloom?','Better surface-to-volume ratios, and they can swim out of low nutrient concentrations',6,0);
INSERT INTO "recall_pair" VALUES(345,136,'What causes an autumn bloom?','Increasing winds mix harder and entrain nutrients from depth',7,0);
INSERT INTO "recall_pair" VALUES(346,136,'What happens to the spring and autumn blooms in polar regions?','They often merge into a single summer bloom',7,0);
INSERT INTO "recall_pair" VALUES(347,137,'What keeps summer phytoplankton biomass down even though primary production is still high?','Zooplankton eat it nearly as fast as it is produced',8,0);
INSERT INTO "recall_pair" VALUES(348,138,'How does turbulent diffusion change with depth, and what does that do to the mixed layer as summer runs on?','It decreases with depth, so the mixed layer up top is depleted fast',3,0);
INSERT INTO "recall_pair" VALUES(349,138,'Once the mixed layer is depleted in summer, where does high productivity move to?','Down toward the pycnocline, where nutrients are cycled up',3,0);
INSERT INTO "recall_pair" VALUES(350,140,'What usually causes transient patches of high surface chlorophyll in the open ocean?','Episodic upwelling events',3,0);
INSERT INTO "recall_pair" VALUES(351,140,'Why are high-chlorophyll surface patches far from the nutricline only transient?','Phytoplankton are very good at depleting those surface waters',3,0);
INSERT INTO "recall_pair" VALUES(352,141,'Besides nutrient depletion up top, what other effect drives the chlorophyll maximum deeper?','With less sunlight phytoplankton grow slower, so they lack the boom capacity to deplete the nutrients — things stay more balanced',3,0);
INSERT INTO "recall_pair" VALUES(353,142,'Which way does the depth of the chlorophyll maximum trend as you go north, and why?','It rises — the maximum deepens as summer goes on, and summer is later the further poleward you go',5,0);
INSERT INTO "recall_pair" VALUES(354,200,'Where do many stocks of herring breed?','Where there is significant tidal mixing',9,0);
INSERT INTO "recall_pair" VALUES(355,201,'How do gyres form around shallow banks?','Tidal currents moving on and off the bank interact with bottom topography to generate unidirectional currents',6,0);
INSERT INTO "recall_pair" VALUES(356,201,'What is the tidally mixed water over a bank, plus its gyre, believed to be good for?','Many fish eggs and larvae',6,0);
INSERT INTO "recall_pair" VALUES(357,202,'Name the four components of the tides.','Lunar semi-diurnal, solar semi-diurnal, luni-solar diurnal, principal lunar diurnal',8,0);
INSERT INTO "recall_pair" VALUES(358,202,'What range of tidal forms do the four components allow?','From semi-diurnal through to diurnal',8,0);
INSERT INTO "recall_pair" VALUES(359,203,'Why do internal waves create divergence and convergence zones?','Their waveforms set up rotations',7,0);
INSERT INTO "recall_pair" VALUES(360,203,'How does a slick form over an internal wave''s convergence?','Biomass accumulates there and raises the surface tension',7,0);
INSERT INTO "recall_pair" VALUES(361,204,'What is a lee wave?','An internal wave created by water flowing over an obstacle — a shelf break will do',6,0);
INSERT INTO "recall_pair" VALUES(362,205,'What is the retention hypothesis for fish larvae?','Rectification of currents at banks and tidally mixed water creates a barrier holding pelagic larvae roughly in place',6,0);
INSERT INTO "recall_pair" VALUES(363,205,'What is the alternative to retention as an explanation for spawning at banks?','The eggs are laid downstream of a lot of food, and larvae move vertically to catch the currents they need',6,0);
INSERT INTO "recall_pair" VALUES(364,206,'In one experiment, how much material did internal-wave slicks bring inshore from offshore?','90% of it',5,0);
INSERT INTO "recall_pair" VALUES(365,206,'How do megalops larvae appear to use internal-wave slicks?','They swim to the surface and let the slicks carry them inshore',5,0);
INSERT INTO "recall_pair" VALUES(366,207,'What can islands do when they interact with tidal currents?','Create internal waves that may boost primary productivity',6,0);
INSERT INTO "recall_pair" VALUES(367,227,'How do Eulachon eggs become adhesive?','The outer of their two membranes ruptures, sticking the egg to the substrate.',0,0);
INSERT INTO "recall_pair" VALUES(368,228,'Where do Eulachon larvae go on hatching, and where may they rear?','Straight downstream; they may rear in estuaries.',0,0);
INSERT INTO "recall_pair" VALUES(369,229,'Eulachon larval outmigration is thought to occur under what light conditions?','Low light.',0,0);
INSERT INTO "recall_pair" VALUES(370,230,'Young Eulachon can be found schooling with which other species?','Anchovy and herring.',0,0);
INSERT INTO "recall_pair" VALUES(371,231,'Eulachon abundance is thought to drive the migrations of which fish?','Sturgeon.',0,0);
INSERT INTO "recall_pair" VALUES(372,232,'Some people locate Eulachon migrations by what sign?','Conspicuous aggregations of their predators.',0,0);
INSERT INTO "recall_pair" VALUES(373,233,'Which two marine mammals turn up to feed on Eulachon runs?','Harbor seals and Steller sea lions.',0,0);
INSERT INTO "recall_pair" VALUES(374,234,'What share of the global cephalopod catch reported by FAO is not resolved to single species?','Over 50%.',0,0);
INSERT INTO "recall_pair" VALUES(375,235,'One Antarctic expedition turned up how many cephalopod species new to science?','At least seven.',0,0);
INSERT INTO "recall_pair" VALUES(376,236,'Which cephalopod order holds the "true" squids?','Teuthida.',0,0);
INSERT INTO "recall_pair" VALUES(377,236,'Among cephalopod orders, how do the Teuthida rank in diversity?','Most diverse.',0,0);
INSERT INTO "recall_pair" VALUES(378,237,'Which order contains all the octopus species?','Octopodida.',0,0);
INSERT INTO "recall_pair" VALUES(379,238,'Octopus are not all benthic — what other habitat do some families occupy?','Pelagic, the open water.',0,0);
INSERT INTO "recall_pair" VALUES(380,239,'The hectocotylus is what?','A cephalopod''s sperm-delivery arm.',0,0);
INSERT INTO "recall_pair" VALUES(381,239,'In what strange way do some octopus use the hectocotylus?','It detaches — left inside the female''s mantle to fertilize.',0,0);
INSERT INTO "recall_pair" VALUES(382,240,'Do cephalopods occur in non-marine waters?','No — they are exclusively marine.',0,0);
INSERT INTO "recall_pair" VALUES(383,240,'What kinds of habitats do cephalopods occupy?','Virtually all marine habitats.',0,0);
INSERT INTO "recall_pair" VALUES(384,241,'The Mid-Atlantic Ridge is how long?','14,000 km',18,0);
INSERT INTO "recall_pair" VALUES(385,241,'The global mid-ocean ridge is how long?','More than 40,000 km',18,0);
INSERT INTO "recall_pair" VALUES(386,241,'The most extensive feature of the earth''s topography is what?','The global mid-ocean ridge',18,0);
INSERT INTO "recall_pair" VALUES(387,241,'The mid-ocean ridge runs from where to where?','From the Arctic Ocean through Iceland, down the middle of the Atlantic, around the tip of Africa, through the Indian and Pacific, ending in the Gulf of California',18,0);
INSERT INTO "recall_pair" VALUES(388,242,'Going seaward from land, what are the main divisions of the sea floor?','Shore, continental shelf, continental slope and rise, deep-sea bottom',18,0);
INSERT INTO "recall_pair" VALUES(389,242,'The abyssal plain is part of which division?','The deep-sea bottom',18,0);
INSERT INTO "recall_pair" VALUES(390,243,'The Atlantic Ocean grows at what rate?','A few centimeters a year',18,0);
INSERT INTO "recall_pair" VALUES(391,243,'What makes the Atlantic grow?','Material added at the center of the Mid-Atlantic Ridge pushes the plates apart',18,0);
INSERT INTO "recall_pair" VALUES(392,244,'A marginal sea is what?','A fairly large basin of salt water connected to the open ocean by one or more fairly narrow channels',18,0);
INSERT INTO "recall_pair" VALUES(393,245,'A sill is what?','A ridge above the average bottom level of a region, separating one basin from another',16,0);
INSERT INTO "recall_pair" VALUES(394,245,'In a fjord, a sill separates what from what?','The landward basin from the sea outside',16,0);
INSERT INTO "recall_pair" VALUES(395,246,'Deep and bottom waters cross ridges through what?','Fracture zones — narrow gaps in the ridge',17,0);
INSERT INTO "recall_pair" VALUES(396,246,'Which fracture zone is an important pathway for abyssal circulation in the Atlantic?','The Romanche Fracture Zone, through the MAR close to the equator',17,0);
INSERT INTO "recall_pair" VALUES(397,247,'The world''s two sources of deep water are where?','The northern North Atlantic and the Southern Ocean',18,0);
INSERT INTO "recall_pair" VALUES(398,247,'The densest bottom waters of the world ocean form where?','The Southern Ocean',18,0);
INSERT INTO "recall_pair" VALUES(399,248,'Coasts are called erosional or depositional depending on what?','Whether material is removed or added',18,0);
INSERT INTO "recall_pair" VALUES(400,249,'The continental shelf has what average gradient?','1 in 500',18,0);
INSERT INTO "recall_pair" VALUES(401,249,'The shelf break sits where the gradient increases to what?','About 1 in 20, forming the continental slope',18,0);
INSERT INTO "recall_pair" VALUES(402,250,'Deep currents moving bottom sediments commonly form what?','Undersea dunes and canyons',17,0);
INSERT INTO "recall_pair" VALUES(403,251,'Turbidity currents are common where?','On continental slopes',18,0);
INSERT INTO "recall_pair" VALUES(404,251,'A turbidity current carries what?','A mixture of water and sediment',18,0);
INSERT INTO "recall_pair" VALUES(405,251,'Turbidity currents are driven by what?','The instability of the sediments under gravity, not by forces within the water',18,0);
INSERT INTO "recall_pair" VALUES(406,251,'Turbidity currents run downslope at speeds up to what?','100 km/h',18,0);
INSERT INTO "recall_pair" VALUES(407,252,'The Denmark Strait lies between what?','Greenland and Iceland',18,0);
INSERT INTO "recall_pair" VALUES(408,252,'Dense water formed in the Nordic Seas spills into the Atlantic over which ridge?','The Denmark Strait',18,0);
INSERT INTO "recall_pair" VALUES(409,253,'The oceans divide the world ocean area in what proportions?','Pacific ~46%, Atlantic ~23%, Indian ~20%, the rest ~11%',18,0);
INSERT INTO "recall_pair" VALUES(410,254,'In all oceans, what separates the bottom waters?','The mid-ocean ridge and other deep ridges',18,0);
INSERT INTO "recall_pair" VALUES(411,254,'How can you see that ridges separate bottom waters?','Water properties differ east and west of the ridge',18,0);
INSERT INTO "recall_pair" VALUES(412,255,'The Southern Ocean is considered separately for what reason?','It is the only region outside the Arctic with a path for eastward flow all the way around the globe',18,0);
INSERT INTO "recall_pair" VALUES(413,256,'Why can no cold, dense water form in the Indian Ocean?','It has no high northern latitudes',18,0);
INSERT INTO "recall_pair" VALUES(414,257,'Water has the highest heat capacity of all liquids except which?','Ammonia',17,0);
INSERT INTO "recall_pair" VALUES(415,258,'What share of the anthropogenic heating from climate change is stored in the ocean?','About 90%',17,0);
INSERT INTO "recall_pair" VALUES(416,258,'Why does the ocean hold most of the anthropogenic heating?','Water is such an effective heat reservoir',17,0);
INSERT INTO "recall_pair" VALUES(417,259,'Heating seawater does what to its density?','Lowers it — molecular activity increases and the water expands thermally',17,0);
INSERT INTO "recall_pair" VALUES(418,260,'For the normal range of ocean salinity, maximum density occurs at what temperature?','At the freezing point, which is depressed to well below 0 °C',17,0);
INSERT INTO "recall_pair" VALUES(419,260,'Fresh water reaches its maximum density at what temperature?','About 4 °C, not at its freezing point',17,0);
INSERT INTO "recall_pair" VALUES(420,261,'A pressure change of 1 dbar corresponds to what depth change?','Slightly less than 1 m',17,0);
INSERT INTO "recall_pair" VALUES(421,262,'In most of the ocean, what is the primary determinant of density?','Temperature',17,0);
INSERT INTO "recall_pair" VALUES(422,262,'Where is salinity the primary determinant of density?','High latitude regions of excess rainfall or sea ice processes',17,0);
INSERT INTO "recall_pair" VALUES(423,263,'The ocean''s temperature runs over what range?','From the freezing point, around −1.7 °C depending on salinity, to about 30 °C in the tropics',17,0);
INSERT INTO "recall_pair" VALUES(424,264,'Heat content per unit volume is computed how?','$Q = r_c \rho T$',17,0);
INSERT INTO "recall_pair" VALUES(425,264,'In $Q = r_c \rho T$, what are the three terms?','$T$ temperature in Kelvin, $\rho$ seawater density, $r_c$ the specific heat of seawater',17,0);
INSERT INTO "recall_pair" VALUES(426,265,'Compressing a water parcel with no heat exchange does what to its temperature?','Raises it — adiabatic compression',17,0);
INSERT INTO "recall_pair" VALUES(427,265,'Is seawater compressible?','Almost, but not quite, incompressible — a pressure increase compresses a parcel slightly',17,0);
INSERT INTO "recall_pair" VALUES(428,266,'Potential temperature is what?','The temperature a water parcel would have if moved adiabatically to another pressure',17,0);
INSERT INTO "recall_pair" VALUES(429,267,'The adiabatic lapse rate is what?','The change in temperature per unit change in pressure for an adiabatic displacement of a water parcel',17,0);
INSERT INTO "recall_pair" VALUES(430,268,'A parcel at 5 °C and salinity 35.00 lowered adiabatically from the surface to 4000 m ends at what temperature?','5.45 °C',17,0);
INSERT INTO "recall_pair" VALUES(431,269,'What stays nearly constant across the ocean even though total dissolved matter varies?','The ratios of the more abundant dissolved components',17,0);
INSERT INTO "recall_pair" VALUES(432,269,'Why are the ratios of the major dissolved components so uniform?','Weathering adds them very slowly over millions of years, so mixing distributes them evenly',17,0);
INSERT INTO "recall_pair" VALUES(433,270,'The dominant source of the ocean''s salts is what?','River runoff from weathering of the continents',17,0);
INSERT INTO "recall_pair" VALUES(434,270,'Salinity differences from place to place come from what?','Evaporation, and dilution by freshwater from rain and river runoff',17,0);
INSERT INTO "recall_pair" VALUES(435,270,'Where do evaporation and dilution act on salinity?','Only at the sea surface',17,0);
INSERT INTO "recall_pair" VALUES(436,271,'Mixing is most efficient between waters of what?','The same density — stirring along them is adiabatic',17,0);
INSERT INTO "recall_pair" VALUES(437,271,'Why are ocean property distributions mapped on isopycnal surfaces?','Mixing runs along surfaces of equal density, so such maps — built to be closest to isentropic — depict the distributions effectively',17,0);
INSERT INTO "recall_pair" VALUES(438,272,'Potential density is what?','Density computed with potential temperature in place of temperature and a single reference pressure in place of the in-situ pressure',17,0);
INSERT INTO "recall_pair" VALUES(439,272,'Does the reference pressure for potential density have to be 0 dbar?','No — it is a single chosen reference pressure, not necessarily the surface',17,0);
INSERT INTO "recall_pair" VALUES(440,273,'How does the compressibility of seawater change with temperature?','Cold water is more compressible — a cold parcel is easier to deform than a warm one',17,0);
INSERT INTO "recall_pair" VALUES(441,274,'An isentropic surface is what?','One along which water parcels can move adiabatically — without external input of heat or salt',17,0);
INSERT INTO "recall_pair" VALUES(442,275,'Why are there no closed, unique isentropic surfaces in the ocean?','A parcel returning to its original latitude and longitude has mixed along the way, so its temperature and salinity — and hence its density and pressure — have changed',17,0);
INSERT INTO "recall_pair" VALUES(443,276,'Changing the reference pressure for potential density does what?','Alters the density difference between two water parcels',17,0);
INSERT INTO "recall_pair" VALUES(444,277,'Thermobaricity is best explained by what?','The rotation with depth of potential density contours in the potential temperature–salinity plane',17,0);
INSERT INTO "recall_pair" VALUES(445,278,'Double diffusion results from what?','The difference between the molecular diffusivities of heat and salt — not from linearity or nonlinearity',17,0);
INSERT INTO "recall_pair" VALUES(446,279,'Static stability, $E$, measures what?','The tendency of a water column to overturn',16,0);
INSERT INTO "recall_pair" VALUES(447,279,'Static stability is higher where the water column is what?','More stratified in density',16,0);
INSERT INTO "recall_pair" VALUES(448,279,'A water column is statically stable when what happens?','A parcel moved adiabatically up or down a short distance returns to its original position',16,0);
INSERT INTO "recall_pair" VALUES(449,279,'What sets how vigorously a displaced parcel returns to its original position?','The density difference between the parcel and the surrounding water at the displaced position',16,0);
INSERT INTO "recall_pair" VALUES(450,280,'A pycnocline is what?','A layer of high stratification',17,0);
INSERT INTO "recall_pair" VALUES(451,281,'Why is the pycnocline a barrier to vertical transport?','Turbulence, which does most of the mixing between water bodies, penetrates a stable pycnocline less easily than less stable layers',17,0);
INSERT INTO "recall_pair" VALUES(452,282,'The buoyancy frequency is the intrinsic frequency associated with what?','Static stability — it is the frequency of internal gravity waves',16,0);
INSERT INTO "recall_pair" VALUES(453,282,'A parcel displaced upward in a statically stable column does what?','Sinks and overshoots its original position, is forced back up into lighter water by the denser water beneath, and keeps oscillating',16,0);
INSERT INTO "recall_pair" VALUES(454,283,'Above what salinity does water reach its maximum density at the freezing point?','24.7 psu',17,0);
INSERT INTO "recall_pair" VALUES(455,283,'In water below 24.7 psu, what does surface cooling do before freezing?','The water reaches maximum density while still fluid and sinks, overturning the column until the whole of it is at the temperature of maximum density',17,0);
INSERT INTO "recall_pair" VALUES(456,283,'In low-salinity water, why does the overturning stop on further cooling?','Past the temperature of maximum density, cooling makes the surface water lighter',17,0);
INSERT INTO "recall_pair" VALUES(457,283,'How does a low-salinity water column freeze?','From the surface down, with the deeper water remaining unfrozen',17,0);
INSERT INTO "recall_pair" VALUES(458,283,'Why is freezing delayed above 24.7 psu compared with the freshwater case?','Maximum density is reached only at the freezing point, so more of the water column must be cooled before freezing can begin',17,0);
INSERT INTO "recall_pair" VALUES(459,284,'A tracer is conservative when what is true?','No significant process other than mixing changes it below the surface',17,0);
INSERT INTO "recall_pair" VALUES(460,284,'Why can salinity, potential temperature and density be used as conservative tracers?','Their sources within the ocean are extremely weak',17,0);
INSERT INTO "recall_pair" VALUES(461,285,'Which two trace isotopes have been widely measured as ocean tracers?','$C_{14}$ and $He_3$',17,0);
INSERT INTO "recall_pair" VALUES(462,285,'Of the two widely measured tracer isotopes, which is conservative?','$He_3$ is conservative; $C_{14}$ is radioactive and non-conservative',17,0);
INSERT INTO "recall_pair" VALUES(463,285,'Where do the anthropogenic sources of $C_{14}$ and $He_3$ sit?','In the upper ocean — both isotopes are predominantly natural otherwise',17,0);
INSERT INTO "recall_pair" VALUES(464,286,'The ratio of the speed of sound in air to that in water is about what?','1:4.5',17,0);
INSERT INTO "recall_pair" VALUES(465,286,'The ratio of the speed of light in air to that in water is about what?','1.33:1',17,0);
INSERT INTO "recall_pair" VALUES(466,286,'Why can a person on the shore see into the water but not hear anything in it?','The large sound-speed contrast lets only a small amount of sound energy cross the air/water interface, while light passes relatively efficiently',17,0);
INSERT INTO "recall_pair" VALUES(467,286,'Why can divers not converse underwater?','Their sounds are generated in the air in the throat, and little of that energy is transmitted into the water',17,0);
INSERT INTO "recall_pair" VALUES(468,287,'How does the compressibility of a medium affect wave speed through it?','The more compressible the medium at a given density, the slower the wave — more activity is needed to move the molecules',16,0);
INSERT INTO "recall_pair" VALUES(469,288,'In the upper ocean, how does sound speed change with depth?','It is high where the water is warm and decreases downward as temperature falls',17,0);
INSERT INTO "recall_pair" VALUES(470,288,'What reverses the downward decrease in sound speed at middepth?','Pressure increasing with depth overcomes the effect of the cooler water',17,0);
INSERT INTO "recall_pair" VALUES(471,288,'Where does sound speed reach its maxima and its minimum in most of the ocean?','Maxima at the surface (warm water) and the bottom (high pressure), with a minimum in between',17,0);
INSERT INTO "recall_pair" VALUES(472,288,'The sound-speed minimum at middepth is called what?','The SOFAR channel — SOund Fixing And Ranging',17,0);
INSERT INTO "recall_pair" VALUES(473,289,'5 cm of new powder snow insulates like how much ice?','250–350 cm',17,0);
INSERT INTO "recall_pair" VALUES(474,289,'5 cm of settled snow insulates like how much ice?','60–100 cm',17,0);
INSERT INTO "recall_pair" VALUES(475,289,'5 cm of hard-packed snow insulates like how much ice?','20–30 cm',17,0);
INSERT INTO "recall_pair" VALUES(476,290,'Subtropical refers to which zones?','The mid-latitude zones poleward of the tropics',14,0);
INSERT INTO "recall_pair" VALUES(477,290,'What characterizes the subtropical zones atmospherically?','Atmospheric high pressure centers',14,0);
INSERT INTO "recall_pair" VALUES(478,291,'A water mass is what?','A body of water whose properties were set by a single identifiable process',17,0);
INSERT INTO "recall_pair" VALUES(479,291,'Where are most water masses formed?','At the sea surface',17,0);
INSERT INTO "recall_pair" VALUES(480,292,'Mediterranean Water is identified by what characteristic?','A salinity maximum at middepth in the North Atlantic',17,0);
INSERT INTO "recall_pair" VALUES(481,292,'Mediterranean Water sits at what depth in the North Atlantic?','1000–2000 m',17,0);
INSERT INTO "recall_pair" VALUES(482,293,'Subtropical Mode Water is identified by which vertical extremum?','Its thickness',17,0);
INSERT INTO "recall_pair" VALUES(483,293,'Subtropical Mode Water originates how?','In a thick surface winter mixed layer, then advected down along isopycnals into the ocean interior',17,0);
INSERT INTO "recall_pair" VALUES(484,293,'What do Mode Waters generally have in common?','They originate in a thick winter mixed layer that is advected along isopycnals into the interior',17,0);
INSERT INTO "recall_pair" VALUES(485,294,'A thermostad is what?','A less stratified, more isothermal layer lying between two thermoclines',17,0);
INSERT INTO "recall_pair" VALUES(486,294,'Where are two thermoclines with a thermostad between them often found, and over what depth?','In the western subtropical regions and elsewhere, all within the upper 1000 m',17,0);
INSERT INTO "recall_pair" VALUES(487,295,'The warm pool sits where?','The western tropical Pacific, through the Indonesian passages and into the tropical Indian Ocean — the warmest SST region',17,0);
INSERT INTO "recall_pair" VALUES(488,295,'The cold tongue is what?','The narrow tongue of colder water along the equator in the eastern Pacific and Atlantic',17,0);
INSERT INTO "recall_pair" VALUES(489,295,'The cold tongue forms how?','Upwelling of thermocline water along the equator',17,0);
INSERT INTO "recall_pair" VALUES(490,296,'How deep do wind-stirred mixed layers reach, as a rule of thumb?','Not much deeper than 100–150 m',17,0);
INSERT INTO "recall_pair" VALUES(491,296,'When do wind-stirred mixed layers reach their greatest depth?','At the end of winter — winter mixed layers are much thicker than summer ones in all regions',17,0);
INSERT INTO "recall_pair" VALUES(492,297,'What temperature difference marks the base of the mixed layer?','0.2 °C',17,0);
INSERT INTO "recall_pair" VALUES(493,298,'At low and middle latitudes, the permanent thermocline sits at what depths?','Between 200 and 1000 m',12,0);
INSERT INTO "recall_pair" VALUES(494,298,'What is the thermocline always present at low and middle latitudes called?','The main, or permanent, thermocline',12,0);
INSERT INTO "recall_pair" VALUES(495,299,'In polar and subpolar waters, which permanent feature replaces the thermocline?','A permanent halocline — there is often no permanent thermocline',17,0);
INSERT INTO "recall_pair" VALUES(496,299,'Why do polar and subpolar waters often lack a permanent thermocline?','The surface waters there may be colder than the deep waters',17,0);
INSERT INTO "recall_pair" VALUES(497,300,'What are the two hypotheses for why the thermocline exists?','Subduction of surface waters from farther poleward, and upwelling of cold water from below balanced by heat diffusion from above',17,0);
INSERT INTO "recall_pair" VALUES(498,300,'In the subduction hypothesis, where does subtropical thermocline water originate?','As surface water farther to the north, which subducts beneath the warmer surface water to the south as it moves',17,0);
INSERT INTO "recall_pair" VALUES(499,300,'In the subduction hypothesis, what builds the structure of the main pycnocline?','The subduction of many layers, building up the temperature, salinity and density structure of the subtropical gyre',17,0);
INSERT INTO "recall_pair" VALUES(500,300,'In the second hypothesis, what creates the thermocline''s exponential profile?','Upwelling of cold water from below together with heat diffusion from above',17,0);
INSERT INTO "recall_pair" VALUES(501,301,'The thermocline water mass is called what?','Central Water',16,0);
INSERT INTO "recall_pair" VALUES(502,301,'How does Central Water differ from a typical water mass?','It spans a large range of temperature, salinity and density',16,0);
INSERT INTO "recall_pair" VALUES(503,302,'Below what depth are annual temperature variations rarely perceptible?','100–300 m — annual variation decreases with depth',12,0);
INSERT INTO "recall_pair" VALUES(504,303,'Surface temperature peaks in which months in the Northern Hemisphere?','August/September, at the end of the warming season',17,0);
INSERT INTO "recall_pair" VALUES(505,303,'Surface temperature bottoms out in which months in the Northern Hemisphere?','February/March, at the end of the cooling season',17,0);
INSERT INTO "recall_pair" VALUES(506,304,'Below the thermocline, how does temperature change with depth?','It decreases slowly — far more slowly than through the thermocline',17,0);
INSERT INTO "recall_pair" VALUES(507,304,'In the deepest waters, temperature can do what toward the bottom?','Rise — high pressure compresses the water and raises its temperature adiabatically',17,0);
INSERT INTO "recall_pair" VALUES(508,305,'Diurnal temperature variations of 1 °C or more occur under what conditions?','High insolation and low wind speed',14,0);
INSERT INTO "recall_pair" VALUES(509,305,'How deep do the larger diurnal temperature variations reach?','Generally only the upper few meters',14,0);
INSERT INTO "recall_pair" VALUES(510,306,'Which is the saltiest ocean?','The Atlantic, especially the North Atlantic',17,0);
INSERT INTO "recall_pair" VALUES(511,306,'Which is the freshest ocean, excluding the Arctic and Southern Ocean?','The Pacific — though the Arctic and Southern Ocean are both fresher still',17,0);
INSERT INTO "recall_pair" VALUES(512,307,'Surface salinity is set climatologically by which opposing effects?','Evaporation raises it; precipitation, runoff and ice melt lower it',17,0);
INSERT INTO "recall_pair" VALUES(513,307,'Which single map mostly captures what sets surface salinity?','The map of evaporation minus precipitation',17,0);
INSERT INTO "recall_pair" VALUES(514,308,'Does potential density increase uniformly with depth?','No — like potential temperature, it does not',17,0);
INSERT INTO "recall_pair" VALUES(515,308,'The vertical structure of density resembles that of what?','Potential temperature',17,0);
INSERT INTO "recall_pair" VALUES(516,309,'A layer where density increases rapidly with depth is called what?','A pycnocline — analogous to the thermocline',15,0);
INSERT INTO "recall_pair" VALUES(517,309,'Layers of lower vertical density gradient are called what?','Pycnostads',15,0);
INSERT INTO "recall_pair" VALUES(518,310,'Why is potential density structure simpler than that of potential temperature and salinity?','The water column must be vertically stable',17,0);
INSERT INTO "recall_pair" VALUES(519,311,'What are the three ways things are physically changed inside the ocean?','Radiation, advection, and diffusion',16,0);
INSERT INTO "recall_pair" VALUES(520,311,'Radiation moves things how?','As electromagnetic waves — heat and light',16,0);
INSERT INTO "recall_pair" VALUES(521,311,'Advection moves things how?','The movement of a fluid parcel carries its properties, such as heat and salt, with it',16,0);
INSERT INTO "recall_pair" VALUES(522,311,'Diffusion moves things how?','Molecules or tiny parcels of water bump around randomly — turbulence — carrying their properties with them',16,0);
INSERT INTO "recall_pair" VALUES(523,312,'Flux relates to transport how?','Flux is transport per unit area',16,0);
INSERT INTO "recall_pair" VALUES(524,313,'Fick''s law of diffusion says what?','The diffusive flux of a substance is proportional to its concentration gradient',16,0);
INSERT INTO "recall_pair" VALUES(525,313,'Under Fick''s law, what does a constant concentration gradient produce?','No overall change — and no gradient means nothing happens at all',16,0);
INSERT INTO "recall_pair" VALUES(526,314,'Knudsen''s relations give the inflow and outflow of a region how?','$V_i = FS_o/(S_i - S_o)$ and $V_o = FS_i/(S_i - S_o)$',16,0);
INSERT INTO "recall_pair" VALUES(527,314,'In Knudsen''s relations, what are the terms?','$V_i$ water flowing in, $V_o$ water flowing out, $S_i$ and $S_o$ their salinities, $F$ the freshwater input over the area',16,0);
INSERT INTO "recall_pair" VALUES(528,315,'What are the five terms of the heat budget?','$Q_s$, $Q_b$, $Q_h$, $Q_e$, $Q_v$',16,0);
INSERT INTO "recall_pair" VALUES(529,315,'In the heat budget, $Q_s$ and $Q_b$ are what?','$Q_s$ shortwave radiation; $Q_b$ back radiation (longwave)',16,0);
INSERT INTO "recall_pair" VALUES(530,315,'In the heat budget, $Q_h$ is what?','The rate of heat loss or gain through the sea surface by conduction — sensible heat',16,0);
INSERT INTO "recall_pair" VALUES(531,315,'In the heat budget, $Q_e$ is what?','The rate of heat loss or gain by evaporation and condensation — latent heat',16,0);
INSERT INTO "recall_pair" VALUES(532,315,'In the heat budget, $Q_v$ is what?','The rate of heat loss or gain by a water body due to currents',16,0);
INSERT INTO "recall_pair" VALUES(533,316,'Which heat budget term is the largest, and what is its sign?','Shortwave radiation $Q_s$ — always positive',16,0);
INSERT INTO "recall_pair" VALUES(534,316,'Which heat budget term is the second largest?','Latent heat flux $Q_e$, which varies strongly with season',16,0);
INSERT INTO "recall_pair" VALUES(535,316,'Which heat budget term has the smallest variations?','Longwave radiation $Q_b$',16,0);
INSERT INTO "recall_pair" VALUES(536,316,'The sensible heat flux $Q_h$ is largest where?','The northwestern North Atlantic and North Pacific — though it is generally the smallest term',16,0);
INSERT INTO "recall_pair" VALUES(537,317,'Stefan''s Law states what?','All bodies radiate energy at a rate proportional to the fourth power of their absolute temperature',16,0);
INSERT INTO "recall_pair" VALUES(538,317,'Wien''s Law gives the peak wavelength of radiation how?','$l_m T = 2897$ μm K, with $T$ the absolute temperature of the radiating body',16,0);
INSERT INTO "recall_pair" VALUES(539,317,'What does Wien''s Law imply about hotter bodies?','They radiate preferentially at shorter wavelengths',16,0);
INSERT INTO "recall_pair" VALUES(540,317,'Why is radiation shortwave coming in and longwave going out?','The incoming radiation comes from the very hot sun, the outgoing from the much cooler earth',16,0);
INSERT INTO "recall_pair" VALUES(541,318,'Why is it cooler near the poles?','The sun is lower, so a beam of given cross-section strikes the sea obliquely and spreads over a larger area',16,0);
INSERT INTO "recall_pair" VALUES(542,318,'A one square meter beam covers what area of calm sea when the sun is directly overhead?','One square meter',16,0);
INSERT INTO "recall_pair" VALUES(543,319,'Clouds do what to longwave back radiation from the sea?','Reduce it',16,0);
INSERT INTO "recall_pair" VALUES(544,319,'What everyday land observation shows clouds reducing back radiation?','Frost from radiative cooling is more frequent on clear nights than cloudy ones',16,0);
INSERT INTO "recall_pair" VALUES(545,320,'Cloud cover in the subtropics is high or low?','Low — and evaporation there greatly dominates precipitation',16,0);
INSERT INTO "recall_pair" VALUES(546,321,'Variations in shortwave radiation reaching the sea are due to what?','Spatially varying cloud cover, which partially blocks the incoming shortwave radiation',16,0);
INSERT INTO "recall_pair" VALUES(547,322,'Incoming longwave radiation from the atmosphere is absorbed where?','In the top millimeters of the sea, unlike shortwave radiation, which penetrates much deeper',16,0);
INSERT INTO "recall_pair" VALUES(548,322,'The outward longwave radiation is set by what temperature?','The skin temperature of the sea — the literal surface, less than a millimeter thick',16,0);
INSERT INTO "recall_pair" VALUES(549,323,'How does the albedo of ice and snow compare with open water, and which flux does that mostly affect?','Much higher albedo — they reflect most incident solar radiation, mostly affecting incoming shortwave',16,0);
INSERT INTO "recall_pair" VALUES(550,323,'How does back radiation loss $Q_b$ from ice compare with that from water?','Much the same, since their surface temperatures are relatively similar',16,0);
INSERT INTO "recall_pair" VALUES(551,323,'Why is the net gain $Q_s - Q_b$ smaller over ice and snow than over water?','Their high albedo cuts the shortwave gain while the back radiation loss stays much the same',16,0);
INSERT INTO "recall_pair" VALUES(552,323,'The ice-albedo feedback works how?','As sea ice melts back, the water absorbs more solar radiation, warms, and melts more ice — a positive feedback',16,0);
INSERT INTO "recall_pair" VALUES(553,324,'Average evaporation from the sea surface is how much per year?','About 120 cm/yr — the sea surface sinking more than 1 m a year',16,0);
INSERT INTO "recall_pair" VALUES(554,325,'Expected evaporation is computed how?','$F = \rho C u (q_s - q_a)$',14,0);
INSERT INTO "recall_pair" VALUES(555,325,'In $F = \rho C u (q_s - q_a)$, what are the terms?','$\rho$ air density, $C$ the transfer coefficient for latent heat, $u$ windspeed at 10 m, $q_s$ 98% of saturated humidity at sea level, $q_a$ the measured humidity',14,0);
INSERT INTO "recall_pair" VALUES(556,326,'What causes the west-to-east variation in $Q_e$ across the stormy western North Atlantic and North Pacific?','Dry winds blowing off the continents, creating greater latent heat flux',16,0);
INSERT INTO "recall_pair" VALUES(557,326,'How does latent heat loss depend on temperature?','Mildly — warmer water evaporates more easily than colder water',16,0);
INSERT INTO "recall_pair" VALUES(558,327,'How large are the seasonal variations in longwave radiation?','Small — as are its geographical variations',16,0);
INSERT INTO "recall_pair" VALUES(559,328,'The Coriolis force deflects a moving body which way in the Northern Hemisphere?','To the right of its direction of motion',16,0);
INSERT INTO "recall_pair" VALUES(560,328,'The Coriolis force deflects a moving body which way in the Southern Hemisphere?','To the left of its direction of motion',16,0);
INSERT INTO "recall_pair" VALUES(561,329,'Why is eddy viscosity introduced?','Turbulent fluids like the ocean and atmosphere mix far more efficiently than molecular viscosity would allow, as if the viscosity were much larger',16,0);
INSERT INTO "recall_pair" VALUES(562,330,'The Coriolis parameter is given by what?','$2\Omega \sin{\phi}$, with $\Omega$ the earth''s rotation rate and $\phi$ the latitude',16,0);
INSERT INTO "recall_pair" VALUES(563,331,'Eddy diffusivity is what?','The equivalent of eddy viscosity for properties like heat and salt',16,0);
INSERT INTO "recall_pair" VALUES(564,331,'Why is eddy diffusivity introduced?','Observed diffusion differs from what molecular diffusion would give',16,0);
INSERT INTO "recall_pair" VALUES(565,332,'Entrainment is what?','The turbulent mixing of a dense plume with the lighter water around it as it flows down a slope',16,0);
INSERT INTO "recall_pair" VALUES(566,332,'Which strait is the example of dense water overflowing a sill as a plume down the continental slope?','The Strait of Gibraltar',16,0);
INSERT INTO "recall_pair" VALUES(567,333,'Stirring between horizontally adjacent waters of strongly contrasting temperature and salinity produces what?','Interleaving, or fine structure, on both sides of the front',16,0);
INSERT INTO "recall_pair" VALUES(568,333,'How thick are the layers of interleaving at a front?','One to tens of meters',16,0);
INSERT INTO "recall_pair" VALUES(569,334,'How much faster does heat diffuse than salt?','About 100 times',16,0);
INSERT INTO "recall_pair" VALUES(570,335,'The net transport integrated through the Ekman layer goes which way in the Northern Hemisphere?','Exactly to the right of the wind',16,0);
INSERT INTO "recall_pair" VALUES(571,335,'The net transport integrated through the Ekman layer goes which way in the Southern Hemisphere?','Exactly to the left of the wind',16,0);
INSERT INTO "recall_pair" VALUES(572,336,'Within the Ekman layer, how does each layer act on the one below it?','Frictional stress proportional to the eddy viscosity accelerates it, turned to the right in the Northern Hemisphere and weaker than the layer above',16,0);
INSERT INTO "recall_pair" VALUES(573,336,'The complete velocity structure of the Ekman layer is called what?','A decaying spiral',16,0);
INSERT INTO "recall_pair" VALUES(574,337,'What creates convergence or divergence within the Ekman layer?','Wind stress varying with position, so that Ekman transport varies with position',16,0);
INSERT INTO "recall_pair" VALUES(575,337,'Convergence in the Ekman layer produces what?','Downwelling of water out of the Ekman layer',16,0);
INSERT INTO "recall_pair" VALUES(576,337,'Divergence in the Ekman layer produces what?','Upwelling of water into the Ekman layer',16,0);
INSERT INTO "recall_pair" VALUES(577,337,'What connects the wind''s frictional forcing of the surface layer to the interior geostrophic circulation?','Ekman convergence and divergence, driving water down out of or up into the Ekman layer',16,0);
INSERT INTO "recall_pair" VALUES(578,338,'Geostrophic balance is a balance between which two forces?','The horizontal pressure gradient and the Coriolis force',16,0);
INSERT INTO "recall_pair" VALUES(579,339,'Geostrophic flow runs which way relative to the pressure contours and the high hills?','Along the contours, with the high hills to the right in the Northern Hemisphere and to the left in the Southern',16,0);
INSERT INTO "recall_pair" VALUES(580,339,'Geostrophic speed at a point is set by what?','The steepness of the slope there — inversely proportional to the separation of the contours',16,0);
INSERT INTO "recall_pair" VALUES(581,340,'Vorticity is what?','Twice the angular velocity at a point in a fluid',16,0);
INSERT INTO "recall_pair" VALUES(582,340,'How is vorticity easiest to visualize?','As a small paddle wheel immersed in the fluid — if the flow turns it, there is vorticity',16,0);
INSERT INTO "recall_pair" VALUES(583,340,'Vorticity is a vector pointing which way?','Out of the plane in which the fluid turns',16,0);
INSERT INTO "recall_pair" VALUES(584,340,'What sets the sign of vorticity?','The right-hand rule — fingers curled in the direction of turning, thumb up is positive, thumb down negative',16,0);
INSERT INTO "recall_pair" VALUES(585,341,'Are water flows steady or unsteady?','Almost all are unsteady',16,0);
INSERT INTO "recall_pair" VALUES(586,341,'When gyre-scale flows break up, what do they break into?','Large eddies, tens to hundreds of kilometers in diameter or larger',16,0);
INSERT INTO "recall_pair" VALUES(587,342,'Westward intensification is what?','The asymmetry of basin-scale circulation — swift narrow currents along the western boundaries, much gentler flow through the vast interior',16,0);
INSERT INTO "recall_pair" VALUES(588,342,'Where does westward intensification occur?','In both hemispheres and in both the subtropical and subpolar gyres',16,0);
INSERT INTO "recall_pair" VALUES(589,342,'Why does westward intensification occur?','The Coriolis force changes across latitudes, and the winds differ — trade winds at the equator against westerlies at higher latitudes',16,0);
INSERT INTO "recall_pair" VALUES(590,343,'Where there is Ekman pumping, the Sverdrup interior flow runs which way?','Equatorward',16,0);
INSERT INTO "recall_pair" VALUES(591,343,'Ekman pumping goes with which sign of wind stress curl?','Negative',16,0);
INSERT INTO "recall_pair" VALUES(592,344,'The westward surface flow along the equator in each of the three oceans is part of what?','The South Equatorial Current',16,0);
INSERT INTO "recall_pair" VALUES(593,344,'What does the westward equatorial surface flow do to sea level across the basin?','Piles water up gently in the west and leaves a depression in the east',16,0);
INSERT INTO "recall_pair" VALUES(594,344,'What drives the Equatorial Undercurrent?','The eastward pressure gradient force, from high pressure in the west to low pressure in the east',16,0);
INSERT INTO "recall_pair" VALUES(595,344,'Which way does the Equatorial Undercurrent flow?','Eastward, along the equator',16,0);
INSERT INTO "recall_pair" VALUES(596,345,'Over the annual cycle, when does surface cooling run from and to?','From around the autumnal equinox almost until the spring equinox',16,0);
INSERT INTO "recall_pair" VALUES(597,345,'When does convection reach its maximum depth and density?','At the end of winter, when the cumulative cooling reaches its maximum',16,0);
INSERT INTO "recall_pair" VALUES(598,345,'How thick can a convective mixed layer be by the end of winter?','Hundreds of meters',16,0);
INSERT INTO "recall_pair" VALUES(599,345,'What limits a wind-stirred mixed layer to about 150 m?','The depth of wind-driven turbulence',16,0);
INSERT INTO "recall_pair" VALUES(600,346,'Deep convection occurs in which few locations worldwide?','The Greenland, Labrador, Mediterranean, Weddell, Ross and Japan (East) Seas',16,0);
INSERT INTO "recall_pair" VALUES(601,347,'Waves are non-dispersive when what is true?','The phase velocity is a single constant for all wavelengths',16,0);
INSERT INTO "recall_pair" VALUES(602,347,'What do dispersive waves do?','Separate from each other, since their phase velocity varies with wavelength',16,0);
INSERT INTO "recall_pair" VALUES(603,348,'A deep-water wave is one whose wavelength compares to the water depth how?','Much shorter than the water depth',16,0);
INSERT INTO "recall_pair" VALUES(604,348,'A shallow-water or long wave is one whose wavelength compares to the water depth how?','Greater than the water depth',16,0);
INSERT INTO "recall_pair" VALUES(605,349,'Whitecaps appear above what wind strength?','About 10 knots (3 m/sec)',16,0);
INSERT INTO "recall_pair" VALUES(606,350,'Swell is what?','The longer, slower, smoother waves left when the wind slows and the shorter waves are damped out',15,0);
INSERT INTO "recall_pair" VALUES(607,350,'Swell wavelengths are on what scale?','Tens of meters',15,0);
INSERT INTO "recall_pair" VALUES(608,350,'How far can swell propagate, and how fast?','Exceedingly far with little damping — from the Gulf of Alaska to Hawaii in a matter of days',15,0);
INSERT INTO "recall_pair" VALUES(609,351,'Why does swell arrive on distant beaches in well-defined sets separated by quiet intervals?','It is often fairly narrow-band in frequency',16,0);
INSERT INTO "recall_pair" VALUES(610,352,'Beaches are classified how, by their interaction with impinging waves?','As dissipative or reflective',16,0);
INSERT INTO "recall_pair" VALUES(611,352,'A dissipative beach has what slope and material?','A mild bottom slope and rough material — both enhance dissipation of wave energy',16,0);
INSERT INTO "recall_pair" VALUES(612,352,'A reflective beach has what slope and material?','More steeply sloped and/or smooth material, reflecting much of the wave energy',16,0);
INSERT INTO "recall_pair" VALUES(613,353,'Waves typically break at what ratio of wave height to depth?','$H/d = 0.8$',16,0);
INSERT INTO "recall_pair" VALUES(614,354,'What are the three types of breaking wave?','Spilling, plunging, and surging breakers',15,0);
INSERT INTO "recall_pair" VALUES(615,354,'Spilling breakers occur on what beach?','The mildest sloping beach',15,0);
INSERT INTO "recall_pair" VALUES(616,354,'Plunging breakers occur on what beach?','A moderately sloping beach',15,0);
INSERT INTO "recall_pair" VALUES(617,354,'Surging breakers occur on what beach, and why?','A steep beach — the wave reaches the beach before it has a chance to break',15,0);
INSERT INTO "recall_pair" VALUES(618,354,'Besides beach slope, what determines the type of breaker?','Wave steepness — the ratio of wave height to wavelength',15,0);
INSERT INTO "recall_pair" VALUES(619,354,'Which breaker type gives the greatest dissipation in the surf zone?','Spilling breakers',15,0);
INSERT INTO "recall_pair" VALUES(620,354,'Which breaker type reflects the most energy back to deep water?','Surging breakers',15,0);
INSERT INTO "recall_pair" VALUES(621,355,'The onshore mass transport from breaking waves is compensated by what?','Offshore flow',16,0);
INSERT INTO "recall_pair" VALUES(622,356,'Internal waves travel where?','Within the ocean itself, between layers of different density',15,0);
INSERT INTO "recall_pair" VALUES(623,356,'How do tides generate internal waves?','They interact with topography, generating internal tides',15,0);
INSERT INTO "recall_pair" VALUES(624,356,'How does the wind generate internal waves?','It stirs the mixed layer, generating waves with frequencies close to the inertial frequency',15,0);
INSERT INTO "recall_pair" VALUES(625,357,'The tide-generating force points which way on each side of the Earth?','Toward the moon on the side facing it, away from the moon on the far side',16,0);
INSERT INTO "recall_pair" VALUES(626,357,'Why does the tide-generating force point away from the moon on the far side of the Earth?','The force there is less than at Earth''s center, while on the near side it is greater',16,0);
INSERT INTO "recall_pair" VALUES(627,358,'Solar tidal forcing compares to lunar tidal forcing how?','About half as strong',16,0);
INSERT INTO "recall_pair" VALUES(628,358,'Why is solar tidal forcing weaker than lunar, despite the sun''s far greater mass?','The sun is much farther away',16,0);
INSERT INTO "recall_pair" VALUES(629,359,'Spring tides occur when?','When Earth, moon and sun are aligned — or the moon exactly opposite the sun — so the lunar and solar tides reinforce',16,0);
INSERT INTO "recall_pair" VALUES(630,359,'Neap tides occur when?','When the moon is perpendicular to the Earth–sun axis, so the lunar and solar tides do not reinforce',16,0);
INSERT INTO "recall_pair" VALUES(631,359,'Which tides give the largest high tides, and which the smallest?','Spring tides the largest; neap tides the two smallest high tides of the month',16,0);
INSERT INTO "recall_pair" VALUES(632,360,'How deep does the Kuroshio Extension reach downstream of the separation point?','To the ocean bottom, in the deepest water',15,0);
INSERT INTO "recall_pair" VALUES(633,361,'How stable is the Kuroshio Extension?','Highly unstable — it meanders',15,0);
INSERT INTO "recall_pair" VALUES(634,361,'How does the Kuroshio Extension produce rings?','Its meanders pinch off',15,0);
INSERT INTO "recall_pair" VALUES(635,362,'What happens to nutrients across the northern frontal zone of the Pacific subtropical gyre?','They jump to higher values in the subpolar surface waters',15,0);
INSERT INTO "recall_pair" VALUES(636,363,'The California Current System has what vertical structure of flow?','A shallow southward current over a deep poleward undercurrent',15,0);
INSERT INTO "recall_pair" VALUES(637,364,'What does the California Current do as the upwelling season progresses?','Moves further and further offshore',15,0);
INSERT INTO "recall_pair" VALUES(638,365,'Upwelling off California in winter is how strong?','Weak or inactive',15,0);
INSERT INTO "recall_pair" VALUES(639,365,'Where is the California Current in winter, and how strong?','Far offshore and relatively weak',15,0);
INSERT INTO "recall_pair" VALUES(640,365,'Which way does the coastal flow off California run in winter?','Northward',15,0);
INSERT INTO "recall_pair" VALUES(641,366,'How does upwelled water in the California Current System move offshore?','In jets, not in a sheet',15,0);
INSERT INTO "recall_pair" VALUES(642,366,'What are the offshore jets of upwelled water off California associated with?','Recurring locations at capes or points in the coastline',15,0);
INSERT INTO "recall_pair" VALUES(643,367,'The upwelled water in the subpolar gyre comes from what depth?','Just below the Ekman layer',15,0);
INSERT INTO "recall_pair" VALUES(644,367,'Why can subpolar gyre upwelling not draw from greater depth?','The strong pycnocline — mainly a halocline, from the low salinity surface layer',15,0);
INSERT INTO "recall_pair" VALUES(645,367,'What does upwelling in the subpolar gyre do to surface nitrate and productivity?','Raises surface nitrate, greatly enhancing biological productivity',15,0);
INSERT INTO "recall_pair" VALUES(646,368,'With increasing depth, does the North Pacific''s subpolar circulation shift location?','No — unlike the subtropical gyre, it stays put',15,0);
INSERT INTO "recall_pair" VALUES(647,368,'How do the subpolar North Pacific''s boundary currents behave with depth?','They weaken but reach far down the water column, even to the bottom',15,0);
INSERT INTO "recall_pair" VALUES(648,369,'The North Pacific Current splits where?','As it approaches the North American continent',15,0);
INSERT INTO "recall_pair" VALUES(649,369,'Where do the two branches of the North Pacific Current go?','South into the California Current System, north into the Alaska Current',15,0);
INSERT INTO "recall_pair" VALUES(650,369,'The Alaska Current forms which sides of which gyre?','The eastern and northern sides of the cyclonic Alaskan Gyre in the Gulf of Alaska',15,0);
INSERT INTO "recall_pair" VALUES(651,370,'The details of the North Pacific Current bifurcation depend on what?','The large-scale wind forcing',14,0);
INSERT INTO "recall_pair" VALUES(652,370,'What drives the interannual and decadal variability of the North Pacific Current bifurcation?','Mainly ENSO and the Pacific Decadal Oscillation',14,0);
INSERT INTO "recall_pair" VALUES(653,371,'The North Pacific Current bifurcation sits at what latitude in winter?','About 45° N',13,0);
INSERT INTO "recall_pair" VALUES(654,371,'The North Pacific Current bifurcation sits at what latitude in summer?','About 50° N',13,0);
INSERT INTO "recall_pair" VALUES(655,372,'The subpolar gyre, including the Alaskan Gyre, intensifies under what atmospheric condition?','An especially strong Aleutian Low',15,0);
INSERT INTO "recall_pair" VALUES(656,372,'Which years bring an especially strong Aleutian Low and an intensified Alaskan Gyre?','El Niño years and years of low PDO',15,0);
INSERT INTO "recall_pair" VALUES(657,373,'What kind of eddies does the Alaska Current contain?','Dramatic, large anticyclonic eddies — permanent, time-dependent components of the circulation',14,0);
INSERT INTO "recall_pair" VALUES(658,373,'What sets the formation sites of the Alaska Current''s eddies?','Bottom topography',14,0);
INSERT INTO "recall_pair" VALUES(659,373,'Which way do the Alaska Current''s eddies propagate after formation, and why does it matter?','Mainly westward into the Gulf of Alaska, transporting coastal properties into the interior',14,0);
INSERT INTO "recall_pair" VALUES(660,373,'Besides the Alaska Current, which current on the northwest side of the Gulf of Alaska is populated by large eddies?','The Alaskan Stream',14,0);
INSERT INTO "recall_pair" VALUES(661,374,'The Southern Oscillation index is based on what?','The pressure difference between two tropical South Pacific locations',14,0);
INSERT INTO "recall_pair" VALUES(662,374,'The Southern Oscillation is closely related to what?','The El Niño state',14,0);
INSERT INTO "recall_pair" VALUES(663,375,'An El Niño event is marked by what in the equatorial ocean?','An unusual excursion of warm water eastward along the equator',14,0);
INSERT INTO "recall_pair" VALUES(664,375,'What winds accompany El Niño?','Weakened southeast Trade Winds in the east and stronger westerlies in the west',14,0);
INSERT INTO "recall_pair" VALUES(665,375,'What winds accompany La Niña?','Stronger southeast Trades in the east, weak westerlies in the far west',14,0);
INSERT INTO "recall_pair" VALUES(666,375,'What does La Niña do to equatorial sea surface temperature?','Cool water extends much further westward along the equator than usual',14,0);
INSERT INTO "recall_pair" VALUES(667,376,'What maintains the atmosphere''s Walker circulation?','The warm-to-cold SST difference along the equator',14,0);
INSERT INTO "recall_pair" VALUES(668,376,'What does the Walker circulation in turn sustain?','The trade winds',14,0);
INSERT INTO "recall_pair" VALUES(669,377,'What are the four steps from normal conditions to a full-blown El Niño?','Trades turn westerly in the western Pacific; an oceanic Kelvin wave shoots eastward along the equator; warm SST anomalies appear in the eastern and central equatorial Pacific; the Walker circulation is disrupted through SST feedback',11,0);
INSERT INTO "recall_pair" VALUES(670,377,'The switch of the trades to westerly winds at the start of an El Niño is often associated with what?','The atmosphere''s 30–60 day Madden-Julian oscillation',11,0);
INSERT INTO "recall_pair" VALUES(671,378,'The most important distinguishing process for Pacific Ocean water properties is what?','The lack of a surface source of very dense water in the North Pacific',14,0);
INSERT INTO "recall_pair" VALUES(672,379,'Why is salinity low at high latitudes in the Pacific?','Excess precipitation',14,0);
INSERT INTO "recall_pair" VALUES(673,380,'What creates the strong halocline in the Pacific subpolar gyre?','The combination of low surface salinity and upwelling',13,0);
INSERT INTO "recall_pair" VALUES(674,380,'Dichothermal Water is what?','The temperature minimum layer under the subpolar halocline, where surface water becomes very cold in winter',13,0);
INSERT INTO "recall_pair" VALUES(675,380,'Dichothermal Water is found where?','The western subpolar gyre and the adjacent Okhotsk and Bering Seas',13,0);
INSERT INTO "recall_pair" VALUES(676,380,'Why does Dichothermal Water show very high oxygen saturation in summer?','Capping by warm surface water, and slight warming of the subsurface temperature-minimum layer',13,0);
INSERT INTO "recall_pair" VALUES(677,380,'Below the Dichothermal Water, how does temperature vary to the bottom?','It increases to a maximum, then decreases to the ocean bottom',13,0);
INSERT INTO "recall_pair" VALUES(678,380,'Mesothermal Water is what?','The temperature maximum layer below the Dichothermal Water',13,0);
